    fn encrypt<'a>(&'a self, iv: &'a [u8;12], plaintext: &'a [u8]) -> crate::crypto::master::MasterCryptoFuture<'a> {
        Box::pin(async move { crate::crypto::encrypt_aead(plaintext,&self.key,iv,&[]).map(zeroize::Zeroizing::new) })
    }
