// =============================================================================
// URL Detection and Processing
// =============================================================================

/**
 * Regular expression to detect URLs in text content.
 * Matches URLs with protocol AND common video platform URLs without protocol.
 * This is more targeted than matching all URLs without protocol to avoid false positives.
 * Matches:
 * - URLs with protocol: https://example.com/path, http://site.com
 * - YouTube URLs without protocol: youtube.com/watch?v=..., youtu.be/VIDEO_ID, www.youtube.com/...
 */
const URL_REGEX =
  /(?:https?:\/\/[^\s\])"'<>]+|(?<![/\w@])(?:(?:www\.|m\.)?youtube\.com\/(?:watch\?v=|embed\/|shorts\/|v\/)[^\s\])"'<>]+|youtu\.be\/[^\s\])"'<>]+))/g;

/**
 * Detects all URLs in the given text content.
 * Returns array of URL matches with their positions.
 * Excludes URLs that are already inside JSON code blocks (embed references).
 *
 * @param text The text content to search
 * @returns Array of {url, startPos, endPos} objects
 */
export function detectUrlsInText(
  text: string,
): Array<{ url: string; startPos: number; endPos: number }> {
  const urls: Array<{ url: string; startPos: number; endPos: number }> = [];

  // Find all code block ranges to exclude URLs within them
  const codeBlockRanges: Array<{ start: number; end: number }> = [];
  const codeBlockPattern = /```[\s\S]*?```/g;
  let blockMatch;
  while ((blockMatch = codeBlockPattern.exec(text)) !== null) {
    codeBlockRanges.push({
      start: blockMatch.index,
      end: blockMatch.index + blockMatch[0].length,
    });
  }

  // Find all URLs
  let match;
  URL_REGEX.lastIndex = 0; // Reset regex state

  while ((match = URL_REGEX.exec(text)) !== null) {
    let url = match[0];
    const startPos = match.index;
    const endPos = startPos + url.length;

    // Check if URL is inside a code block - skip if so
    const isInsideCodeBlock = codeBlockRanges.some(
      (range) => startPos >= range.start && endPos <= range.end,
    );

    if (!isInsideCodeBlock) {
      // Normalize URL by adding https:// if protocol is missing
      if (!/^https?:\/\//i.test(url)) {
        url = `https://${url}`;
      }
      urls.push({ url, startPos, endPos });
    }
  }

  return urls;
}

// =============================================================================
// Embed Reference Protection for PII Detection
// =============================================================================

/**
 * Temporarily replaces embed reference JSON blocks with opaque placeholders so
 * that the PII anonymizer cannot corrupt embed IDs embedded in them.
 *
 * UUID segments can accidentally match PII patterns (e.g. "051-4369" matches the
 * local phone-number regex). Since embed IDs are machine-generated and not
 * sensitive data, they must be preserved verbatim across the PII pass.
 *
 * Usage pattern:
 *   const { safeMarkdown, restore } = protectEmbedRefsFromPII(markdown);
 *   // run PII detection/replacement on safeMarkdown …
 *   markdown = restore(safeMarkdown); // put embed blocks back
 *
 * @param markdown The markdown string that may contain embed reference blocks.
 * @returns An object with the protected markdown and a restore function.
 */
function protectEmbedRefsFromPII(markdown: string): {
  safeMarkdown: string;
  restore: (processed: string) => string;
} {
  // Map from placeholder token → original embed reference block.
  const placeholders = new Map<string, string>();

  // Replace every ```json … ``` block that is an embed reference (has embed_id
  // or embed_ids) with a unique opaque token that cannot trigger PII patterns.
  const safeMarkdown = markdown.replace(
    /```json\n([\s\S]*?)\n```/g,
    (block, content) => {
      try {
        const parsed = JSON.parse(content.trim());
        if ("embed_id" in parsed || "embed_ids" in parsed) {
          // Use a token that contains no digits or PII-like separators so the
          // PII detector cannot match anything inside it.
          const token = `__EMBED_REF_PROTECTED_${placeholders.size}__`;
          placeholders.set(token, block);
          return token;
        }
      } catch {
        // Not valid JSON — leave block as-is for normal PII detection.
      }
      return block;
    },
  );

  const restore = (processed: string): string => {
    let result = processed;
    // Use forEach instead of for...of to avoid requiring downlevelIteration on Maps.
    placeholders.forEach((original, token) => {
      // Use split+join to avoid regex special-character issues in token names.
      result = result.split(token).join(original);
    });
    return result;
  };

  return { safeMarkdown, restore };
}

/**
 * Process all URLs in the message content and convert them to embeds.
 * This is called BEFORE sending a message to ensure URL metadata is fetched
 * and embeds are created with proper embed_ids.
 *
 * @param markdown The markdown content to process
 * @returns Updated markdown with URLs replaced by embed references
 */
async function processUrlsBeforeSend(markdown: string, ignoredEmbedUrls?: ReadonlySet<string>): Promise<string> {
  const urls = detectUrlsInText(markdown).filter(({ url }) => !ignoredEmbedUrls?.has(url));

  if (urls.length === 0) {
    console.debug("[sendHandlers] No URLs to process in message");
    return markdown;
  }

  console.info("[sendHandlers] Processing", urls.length, "URL(s) before send");

  // Process URLs in parallel for better performance
  const embedPromises = urls.map(async (urlInfo) => {
    try {
      console.debug("[sendHandlers] Creating embed for URL", {
        urlLength: urlInfo.url.length,
      });
      const embedResult = await createEmbedFromUrl(urlInfo.url);
      return { urlInfo, embedResult };
    } catch (error) {
      console.error(
        "[sendHandlers] Error creating embed for URL:",
        { urlLength: urlInfo.url.length },
        error,
      );
      return { urlInfo, embedResult: null };
    }
  });

  const embedResults = await Promise.all(embedPromises);

  // Replace URLs with embed references from end to beginning to maintain positions
  const sortedResults = [...embedResults].sort(
    (a, b) => b.urlInfo.startPos - a.urlInfo.startPos,
  );
  let processedMarkdown = markdown;

  for (const { urlInfo, embedResult } of sortedResults) {
    if (!embedResult) {
      console.warn(
        "[sendHandlers] Skipping URL - embed creation failed:",
        { urlLength: urlInfo.url.length },
      );
      continue;
    }

    console.info("[sendHandlers] Replacing URL with embed reference:", {
      urlLength: urlInfo.url.length,
      embed_id: embedResult.embed_id,
      type: embedResult.type,
    });

    // Replace URL with embed reference block
    const beforeUrl = processedMarkdown.substring(0, urlInfo.startPos);
    const afterUrl = processedMarkdown.substring(urlInfo.endPos);

    // Ensure proper spacing around the embed reference block
    let processedBeforeUrl = beforeUrl;
    let processedAfterUrl = afterUrl;

    // Add newline before if there's content and it doesn't end with newline
    if (processedBeforeUrl.length > 0 && !processedBeforeUrl.endsWith("\n")) {
      processedBeforeUrl += "\n";
    }

    // Add newline after if there's content
    if (processedAfterUrl.length > 0 && !processedAfterUrl.startsWith("\n")) {
      processedAfterUrl = "\n" + processedAfterUrl;
    }

    processedMarkdown =
      processedBeforeUrl + embedResult.embedReference + processedAfterUrl;
  }

  console.debug(
    "[sendHandlers] URL processing complete. Processed",
    embedResults.filter((r) => r.embedResult).length,
    "URL(s)",
  );

  return processedMarkdown;
}

// =============================================================================
// Message Creation
// =============================================================================

/**
 * Creates a message payload from markdown content
 * @param markdown The processed markdown content (with URLs already converted to embeds)
 * @param chatId The ID of the current chat
 * @param piiMappings Optional PII mappings for restoration (stored encrypted with message)
 * @returns Message payload object with markdown content
 */
function createMessagePayload(
  markdown: string,
  chatId: string,
  piiMappings?: PIIMapping[],
  senderName = "user",
  existingMessageId?: string,
): Message {
  // Validate markdown content
  if (!markdown || typeof markdown !== "string") {
    console.error("Invalid markdown content:", markdown);
    throw new Error("Invalid markdown content");
  }

  const message_id = existingMessageId ?? `${chatId.slice(-10)}-${crypto.randomUUID()}`;

  // Check WebSocket connection status to determine initial message status
  // If offline, set status to 'waiting_for_internet' instead of 'sending'
  const wsStatus = get(websocketStatus);
  const isConnected = wsStatus.status === "connected";
  const initialStatus: Message["status"] = isConnected
    ? "sending"
    : "waiting_for_internet";

  const message: Message = {
    message_id,
    chat_id: chatId,
    role: "user", // Changed from sender to role
    content: markdown, // Send markdown string directly to server (never Tiptap JSON!)
    status: initialStatus, // Initial status based on connection state
    created_at: Math.floor(Date.now() / 1000), // Unix timestamp in seconds
    sender_name: senderName, // Team member identity is encrypted with the chat key before transport.
    encrypted_content: null, // Will be set during Phase 2 encryption
    // category will be set by server during preprocessing and sent back via chat_metadata_for_encryption
    // PII mappings for client-side restoration (will be encrypted during Phase 2)
    pii_mappings:
      piiMappings && piiMappings.length > 0 ? piiMappings : undefined,
  };

  // current_chat_title removed - not needed for dual-phase architecture

  return message;
}

type E2ESendServerContentOverride = {
  testMockMarker: string;
};

/**
 * Resets the editor content
 * @param editor The TipTap editor instance
 * @param shouldKeepFocus Whether to maintain focus after clearing (default: true on desktop, false on touch)
 */
function resetEditorContent(editor: Editor, shouldKeepFocus?: boolean) {
  // Clear the content. The `false` argument prevents triggering an 'update' event from this specific command.
  // Tiptap's Placeholder extension should handle showing placeholder text if the editor is empty.
  editor.commands.clearContent(false);

  // Determine if we should keep focus based on device type
  // On desktop: keep focus so user can continue typing
  // On touch devices: blur to make input compact and show assistant response better
  const keepFocus =
    shouldKeepFocus !== undefined ? shouldKeepFocus : isDesktop();

  if (keepFocus) {
    editor.commands.focus("end");
    console.debug(
      "[resetEditorContent] Keeping focus on editor (desktop behavior)",
    );
  } else {
    // TipTap schedules commands.blur() for the next animation frame. A failed
    // send may restore this editor's focus before that frame, only to lose it
    // again. Blur now and clear Safari's retained caret only while its anchor
    // still belongs to this editor.
    editor.view.dom.blur();
    const selection = window.getSelection();
    if (selection?.anchorNode && editor.view.dom.contains(selection.anchorNode)) {
      selection.removeAllRanges();
    }
    console.debug(
      "[resetEditorContent] Blurring editor (touch device behavior)",
    );
  }
}

function submittedEmbedNodes(document: JSONContent): JSONContent[] {
  return [
    ...(document.type === "embed" ? [document] : []),
    ...(document.content?.flatMap(submittedEmbedNodes) ?? []),
  ];
}

function setSubmittedEmbedContentRef(
  document: JSONContent, uploadEmbedId: string, localEmbedId: unknown,
): void {
  for (const node of submittedEmbedNodes(document)) {
    if (node.attrs && (node.attrs.uploadEmbedId === uploadEmbedId ||
      (localEmbedId && node.attrs.id === localEmbedId))) {
      node.attrs.contentRef = `embed:${uploadEmbedId}`;
    }
  }
}

/**
 * Guard flag to prevent double-sends on mobile.
 * Mobile browsers (especially Firefox iOS) can fire click/touchend events in rapid succession,
 * causing handleSend to be entered twice before the first invocation completes its async work.
 * This flag blocks re-entry until the first send finishes its critical section
 * (chat creation + dispatch + WebSocket send).
 */
let sendInProgress = false;
// Keep only the current owner's fixed phase name and start time. A duplicate
// invocation replaces the last-step snapshot, so retain its owner's phase
// separately to identify a stalled await without retaining message content.
let activeSendDebugPhase: { step: string; timestamp: string } | null = null;

const DRAFT_SAVE_IDLE_TIMEOUT_MS = 5000;

class PrivacyScanFailedError extends Error {
  constructor(readonly notificationId?: string) {
    super("On-device privacy scan failed");
    this.name = "PrivacyScanFailedError";
  }
}

class PrivacySendContextChangedError extends Error {
  constructor() {
    super("Send context changed during privacy preparation");
    this.name = "PrivacySendContextChangedError";
  }
}

/** Capture settings and authority before an asynchronous scan can yield. */
function captureSendPrivacy(exclusions: ReadonlySet<string>, mappings = getActivePIIMappingsForRewrite()) {
  const settings: PIIDetectionSettings = structuredClone(get(personalDataStore.settings));
  const entries = structuredClone(get(personalDataStore.enabledEntries));
  const settingsFingerprint = JSON.stringify([settings, entries]);
  const team = getActiveTeamContextSnapshot();
  const userId = get(userProfile).user_id;
  const authenticated = get(authStore).isAuthenticated;
  const enhanced = isWebPIIModelEnabled();
  // ActiveChat's Svelte state exposes mapping objects through reactive proxies.
  // Copy the primitive fields into an owner-local snapshot: structuredClone
  // rejects proxies even when their contents are plain serializable strings.
  const mappingSnapshot = mappings.map(({ placeholder, original, type }) => ({ placeholder, original, type }));
  const placeholderOwners = new Map(mappingSnapshot.map((mapping) => [mapping.placeholder, mapping.original]));
  let placeholderSequence = 0;
  const options: PIIDetectionOptions = {
    excludedIds: new Set(exclusions),
    disabledCategories: new Set(Object.entries(settings.categories)
      .filter(([, enabled]) => !enabled).map(([category]) => category)),
    personalDataEntries: entries.map((entry: PersonalDataEntry): PersonalDataForDetection => ({
      id: entry.id, textToHide: entry.textToHide, replaceWith: entry.replaceWith,
      type: entry.type === "address" ? "ADDRESS" : undefined,
      additionalTexts: entry.type === "address" && entry.addressLines
        ? [entry.addressLines.street, entry.addressLines.city].filter((value): value is string => !!value)
        : undefined,
    })),
  };
  const assertAuthorityCurrent = () => {
    if (!isActiveTeamContext(team.teamId, team.epoch) || get(userProfile).user_id !== userId ||
        get(authStore).isAuthenticated !== authenticated || get(forcedLogoutInProgress)) {
      throw new PrivacySendContextChangedError();
    }
  };
  return {
    enabled: settings.masterEnabled,
    enhanced,
    // One lazy budget covers exclusions, recording fields and message text.
    scanContext: createWebPIIScanContext(),
    options,
    mappings: mappingSnapshot,
    failureNotificationId: undefined as string | undefined,
    uniqueMatches(matches: PIIMatch[]): PIIMatch[] {
      return matches.map((match) => {
        let placeholder = match.placeholder;
        if (enhanced && placeholderOwners.has(placeholder) && placeholderOwners.get(placeholder) !== match.match) {
          do {
            placeholder = `${match.placeholder.slice(0, -1)}_${++placeholderSequence}_${crypto.randomUUID().replaceAll("-", "")}]`;
          } while (placeholderOwners.has(placeholder) && placeholderOwners.get(placeholder) !== match.match);
        }
        placeholderOwners.set(placeholder, match.match);
        return placeholder === match.placeholder ? match : { ...match, placeholder };
      });
    },
    assertAuthorityCurrent,
    assertCurrent() {
      assertAuthorityCurrent();
      if (enhanced && settingsFingerprint !== JSON.stringify([
        get(personalDataStore.settings), get(personalDataStore.enabledEntries),
      ])) {
        throw new PrivacySendContextChangedError();
      }
    },
  };
}

type SendPrivacySnapshot = ReturnType<typeof captureSendPrivacy>;
// Pending contexts are memory-only; retain click authority without persisting private state.
const deferredSendPrivacy = new WeakMap<object, SendPrivacySnapshot>();
const pendingPrivacyNotificationIds = new WeakMap<object, string>();
const deferredSubmittedDrafts = new WeakMap<object, {
  editor: Editor;
  document: Editor["state"]["doc"];
  chatId: string;
}>();

function failEnhancedPrivacyScan(privacy: SendPrivacySnapshot): never {
  // SDK failures can contain input text. Only a fixed local message leaves this boundary.
  const notificationId = privacy.failureNotificationId ?? notificationStore.error(get(text)("enter_message.pii.enhanced_scan_failed"));
  throw new PrivacyScanFailedError(notificationId);
}

async function redactTextForSend(markdown: string, privacy: SendPrivacySnapshot) {
  privacy.assertCurrent();
  if (!privacy.enabled) return { markdown, mappings: [] as PIIMapping[], excludedOriginals: new Set<string>() };
  try {
    const { safeMarkdown, restore } = protectEmbedRefsFromPII(markdown);
    const excludedOriginals = await getExcludedOriginalsForCurrentSend(safeMarkdown, privacy.options, privacy.scanContext);
    // A basic-only fallback cannot rediscover an excluded semantic span. Known
    // mappings still have its exact original, so preserve that explicit choice
    // before the history rewrite without depending on another model scan.
    for (const mapping of privacy.mappings) {
      if (privacy.options.excludedIds?.has(modelPIIMatchId(mapping.type as PIIMatch["type"], mapping.original))) {
        excludedOriginals.add(mapping.original);
      }
    }
    privacy.assertCurrent();
    const rewrite = rewriteKnownPIIPlaceholders(safeMarkdown, {
      mappings: privacy.mappings,
      excludedOriginals,
    });
    const detected = await detectPIIForWeb(rewrite.markdown, privacy.options, privacy.scanContext);
    privacy.assertCurrent();
    const matches = privacy.uniqueMatches(detected);
    return {
      markdown: restore(matches.length ? replacePIIWithPlaceholders(rewrite.markdown, matches) : rewrite.markdown),
      mappings: mergePIIMappingsForStorage(rewrite.appliedMappings, createPIIMappingsForStorage(matches)),
      excludedOriginals,
    };
  } catch (error) {
    if (error instanceof PrivacySendContextChangedError) throw error;
    if (privacy.enhanced) failEnhancedPrivacyScan(privacy);
    throw error;
  }
}

/** Recording references include human text inside the protected embed JSON. */
async function redactRecordingFieldsForSend(document: JSONContent, privacy: SendPrivacySnapshot): Promise<PIIMapping[]> {
  if (!privacy.enabled || !privacy.enhanced) return [];
  try {
    let mappings: PIIMapping[] = [];
    let recordingMappings: PIIMapping[] = [];
    const scanned = new Map<string, Awaited<ReturnType<typeof redactTextForSend>>>();
    const redact = async (value: string): Promise<string> => {
      let result = scanned.get(value);
      if (!result) {
        result = await redactTextForSend(value, privacy);
        scanned.set(value, result);
      }
      mappings = mergePIIMappingsForStorage(mappings, result.mappings);
      recordingMappings = mergePIIMappingsForStorage(recordingMappings, result.mappings);
      return result.markdown;
    };
    for (const node of submittedEmbedNodes(document)) {
      if (node.attrs?.type !== "recording") continue;
      recordingMappings = [];
      for (const field of ["title", "filename", "transcript", "transcriptOriginal", "transcriptCorrected"]) {
        const value = node.attrs[field];
        if (typeof value === "string" && value) node.attrs[field] = await redact(value);
      }
      // Deferred uploads have already registered their TOON. Sanitize only human
      // text in that cache too; opaque upload IDs and encryption material stay intact.
      if (privacy.enhanced && typeof node.attrs.contentRef === "string") {
        const { embedStore } = await import("../../../services/embedStore");
        const piiKey = `embed_pii:${node.attrs.contentRef.replace(/^embed:/, "")}`;
        const previousPII = await embedStore.get(piiKey);
        privacy.assertCurrent();
        if (previousPII && typeof previousPII === "object" && Array.isArray(previousPII.pii_mappings)) {
          recordingMappings = mergePIIMappingsForStorage(previousPII.pii_mappings as PIIMapping[], recordingMappings);
          mappings = mergePIIMappingsForStorage(mappings, recordingMappings);
        }
        const persistMappings = async () => {
          if (!recordingMappings.length) return;
          privacy.assertCurrent();
          // Existing owner-only master-key mapping format; never put originals in TOON.
          await embedStore.put(piiKey, {
            embed_id: node.attrs!.contentRef.replace(/^embed:/, ""),
            pii_mappings: recordingMappings,
            created_at: Date.now(),
          }, "audio-recording");
          privacy.assertCurrent();
        };
        const rawStored = await embedStore.get(node.attrs.contentRef);
        privacy.assertCurrent();
        const stored: Record<string, unknown> | undefined = typeof rawStored === "string" ? { content: rawStored } : rawStored;
        if (stored && typeof stored.content !== "string") failEnhancedPrivacyScan(privacy);
        if (!stored && !node.attrs.uploadEmbedId) failEnhancedPrivacyScan(privacy);
        if (stored && typeof stored.content === "string") {
          const { decode, encode } = await import("@toon-format/toon");
          let content: unknown;
          try { content = JSON.parse(stored.content); }
          catch { content = decode(stored.content); }
          if (!content || typeof content !== "object" || Array.isArray(content)) failEnhancedPrivacyScan(privacy);
          const fields = content as Record<string, unknown>;
          for (const field of ["title", "filename", "transcript", "transcript_original", "transcript_corrected"]) {
            const value = fields[field];
            if (typeof value === "string" && value) fields[field] = await redact(value);
          }
          const textPreview = typeof stored.text_preview === "string" ? await redact(stored.text_preview) : stored.text_preview;
          privacy.assertCurrent();
          await persistMappings();
          await embedStore.put(node.attrs.contentRef, { ...stored, content: encode(fields), text_preview: textPreview }, "audio-recording");
          privacy.assertCurrent();
        } else {
          await persistMappings();
        }
      }
    }
    return mappings;
  } catch (error) {
    if (error instanceof PrivacyScanFailedError || error instanceof PrivacySendContextChangedError) throw error;
    if (privacy.enhanced) failEnhancedPrivacyScan(privacy);
    throw error;
  }
}

async function getExcludedOriginalsForCurrentSend(
  markdown: string,
  detectionOptions: PIIDetectionOptions,
  scanContext: WebPIIScanContext,
): Promise<Set<string>> {
  const excludedIds = detectionOptions.excludedIds;
  if (!excludedIds || excludedIds.size === 0) return new Set<string>();

  const matchesWithoutExclusions = await detectPIIForWeb(markdown, {
    ...detectionOptions,
    excludedIds: new Set<string>(),
  }, scanContext);

  return new Set(
    matchesWithoutExclusions
      .filter((match) => excludedIds.has(match.id))
      .map((match) => match.match),
  );
}

function mergePIIMappingsForStorage(
  appliedMappings: PIIMapping[],
  detectedMappings: PIIMapping[],
): PIIMapping[] {
  const merged: PIIMapping[] = [];
  const seen = new Set<string>();

  for (const mapping of [...appliedMappings, ...detectedMappings]) {
    const key = `${mapping.placeholder}\u0000${mapping.original}`;
    if (seen.has(key)) continue;
    seen.add(key);
    merged.push(mapping);
  }

  return merged;
}

/** Prepare a queued-message revision with the same privacy settings as a new send. */
export async function prepareQueuedMessageRevision(
  editorContent: Record<string, unknown>,
  piiExclusions: Set<string>,
  ignoredEmbedUrls?: ReadonlySet<string>,
): Promise<{ content: string; piiMappings: PIIMapping[] }> {
 return legacyEditorProducer.run(async () => {
  const privacy = captureSendPrivacy(piiExclusions);
  const ignoredEmbedUrlsAtClick = new Set(ignoredEmbedUrls);
  const document = structuredClone(editorContent) as JSONContent;
  const recordingMappings = await redactRecordingFieldsForSend(document, privacy);
  let markdown = tipTapToCanonicalMarkdown(document).replace(/^\n+/, "");
  if (!markdown.trim()) throw new Error("Queued message cannot be empty");
  markdown = await processUrlsBeforeSend(markdown, ignoredEmbedUrlsAtClick);
  privacy.assertCurrent();
  const scanPrivacy = privacy.enhanced ? privacy : captureSendPrivacy(privacy.options.excludedIds ?? new Set());
  const redacted = await redactTextForSend(markdown, scanPrivacy);
  return { content: redacted.markdown, piiMappings: mergePIIMappingsForStorage(recordingMappings, redacted.mappings) };

 });
}

function recordSendDebugStep(
  step: string,
  details: Record<string, unknown> = {},
): void {
  const timestamp = new Date().toISOString();
  if (sendInProgress && step !== "send_invoked" && step !== "send_guard_rejected" &&
      step !== "send_set_active_chat_complete") {
    activeSendDebugPhase = { step, timestamp };
  }
  const debugWindow = window as Window & {
    __openmatesLastSendDebug?: Record<string, unknown>;
  };
  debugWindow.__openmatesLastSendDebug = {
    step,
    details,
    timestamp,
  };
}

function serializeSendDebugError(error: unknown): Record<string, unknown> {
  if (error instanceof Error) {
    return {
      name: error.name,
      message: error.message,
      stack: error.stack?.slice(0, 1000) ?? null,
    };
  }

  return { message: String(error) };
}

async function waitForDraftSaveIdle(): Promise<void> {
  if (!get(draftEditorUIState).isSaveInProgress) return;

  console.info(
    "[handleSend] Draft save already in progress; waiting before sending message",
  );

  const deadline = Date.now() + DRAFT_SAVE_IDLE_TIMEOUT_MS;
  while (get(draftEditorUIState).isSaveInProgress && Date.now() < deadline) {
    await new Promise((resolve) => window.setTimeout(resolve, 50));
  }

  if (get(draftEditorUIState).isSaveInProgress) {
    console.warn(
      "[handleSend] Timed out waiting for draft save to finish; continuing send",
    );
  }
}

async function getRawChatForSendClassification(chatId: string): Promise<Chat | null> {
  const transaction = await chatDB.getTransaction(chatDB.CHATS_STORE_NAME, "readonly");
  const store = transaction.objectStore(chatDB.CHATS_STORE_NAME);

  return new Promise((resolve, reject) => {
    const request = store.get(chatId);
    request.onsuccess = () => {
      const rawChat = request.result as Chat | undefined;
      if (rawChat) delete rawChat.messages;
      resolve(rawChat ? { ...rawChat } : null);
    };
    request.onerror = () => reject(request.error);
  });
}

/**
 * Handles sending a message via the message input
 *
 * @param editor TipTap editor instance
 * @param dispatch Event dispatcher function
 * @param setHasContent Function to update hasContent state
 * @param currentChatId Optional current chat ID
 * @param activePIIExclusions Set of PII match IDs that user has clicked to exclude from replacement
 */
export async function handleSend(
  editor: Editor | null,
  dispatch: (type: string, detail?: Record<string, unknown>) => void,
  setHasContent: (value: boolean) => void,
  currentChatId?: string,
  activePIIExclusions: Set<string> = new Set(),
  broadcastToSiblings: boolean = false,
  isSendCancelled: (chatId: string) => boolean = () => false,
  e2eServerContentOverride?: E2ESendServerContentOverride,
  projectFocusDocumentAtSendRequest?: unknown,
  options: { preserveDraft?: boolean; resolveModelSelection?: () => Promise<string>; firstTurnContextAtClick?: boolean; ignoredEmbedUrls?: ReadonlySet<string> } = {},
) {
 return legacyEditorProducer.run(async () => {
  const ignoredEmbedUrlsAtClick = new Set(options.ignoredEmbedUrls);
  // Direct callers must not start a second text inference for the chat owned by
  // a live call. MessageInput routes supported plain text through the call.
  const voiceCall = get(voiceCallController);
  if ((voiceCall.status === 'connecting' || voiceCall.status === 'live') &&
      voiceCall.chatId === currentChatId) return false;
  // Bind this click to its workspace before URL, PII, and draft work can yield.
  const sendContext = getActiveTeamContextSnapshot();
  const senderProfile = get(userProfile);
  const authenticatedAtClick = get(authStore).isAuthenticated;
  const contextIsCurrent = () => isActiveTeamContext(sendContext.teamId, sendContext.epoch) &&
    get(userProfile).user_id === senderProfile.user_id && get(authStore).isAuthenticated === authenticatedAtClick;
  const teamSenderName = sendContext.teamId ? senderProfile.username.trim() || "Team member" : "user";
  const editorTextLength = editor && !editor.isDestroyed ? editor.getText().length : 0;
  console.info("[handleSend] Send invoked", {
    currentChatId,
    hasEditor: !!editor,
    editorDestroyed: editor?.isDestroyed ?? null,
    editorIsEmpty: editor?.isEmpty ?? null,
    textLength: editorTextLength,
  });
  recordSendDebugStep("send_invoked", {
    currentChatId,
    hasEditor: !!editor,
    editorDestroyed: editor?.isDestroyed ?? null,
    editorIsEmpty: editor?.isEmpty ?? null,
    textLength: editorTextLength,
  });

  if (!editor || !hasActualContent(editor)) {
    console.warn("[handleSend] Aborting send because editor has no actual content", {
      currentChatId,
      hasEditor: !!editor,
      editorDestroyed: editor?.isDestroyed ?? null,
      editorIsEmpty: editor?.isEmpty ?? null,
      textLength: editorTextLength,
    });
    vibrateMessageField();
    return;
  }
  let projectFocusIntent: ProjectFocusSendIntent | null = null;
  try {
    // The visible composer can be rebound while the click path awaits local DB
    // readiness. Resolve Project authority from the immutable document captured
    // at the user's click, rather than a later editor instance/state.
    projectFocusIntent = extractProjectFocusSendIntent(
      projectFocusDocumentAtSendRequest ?? editor.getJSON(),
    );
  } catch (error) {
    if (error instanceof ProjectFocusSendPreflightError && error.code === "MULTIPLE_PROJECTS") {
      notificationStore.error("A message can activate one Project at a time.");
      vibrateMessageField();
      return;
    }
    throw error;
  }

  // CRITICAL: Prevent double-sends. On mobile, rapid taps or touch+click can
  // fire this function twice before the first async call reaches setHasContent(false).
  // A double-send during new-chat creation can cause two different chat IDs to be
  // created, leading to messages being routed to the wrong chat (e.g., the user sees
  // their message in the "for everyone" intro chat instead of the new chat).
  if (sendInProgress) {
    recordSendDebugStep("send_guard_rejected", {
      activeSendPhase: activeSendDebugPhase?.step ?? null,
      activeSendPhaseStartedAt: activeSendDebugPhase?.timestamp ?? null,
    });
    console.warn(
      "[handleSend] Send already in progress, ignoring duplicate call",
      { currentChatId, textLength: editorTextLength },
    );
    return;
  }
  sendInProgress = true;
  try {
  recordSendDebugStep("send_guard_acquired", { currentChatId });
  recordSendPreparationPhase('send_accepted');
  const privacyAtClick = captureSendPrivacy(activePIIExclusions);
  const submittedEditorDoc = editor.state.doc;
  const submittedEditorText = editor.getText();
  const submittedEditorJSON = structuredClone(editor.getJSON());
  const submittedEditorContent = structuredClone(submittedEditorJSON);
  const submittedEmbeds = submittedEmbedNodes(submittedEditorContent);
  for (const node of submittedEmbeds) {
    const attrs = node.attrs;
    if (attrs?.status === "finished" && attrs.uploadEmbedId &&
      (attrs.type === "image" || attrs.type === "recording")) {
      setSubmittedEmbedContentRef(submittedEditorContent, attrs.uploadEmbedId as string, attrs.id);
    }
  }
  let clearedEditorDoc: typeof submittedEditorDoc | null = null;
  let optimisticMessageDispatched = false;
  let optimisticMessage: Message | null = null;
  let dispatchedMessage: Message | null = null;
  let sendAccepted = false;
  let queuedDeferredSend = false;
  let persistedMessageId: string | null = null;
  let createdLocalChatId: string | null = null;
  let messageStoredIncognito = false;
  let chatBeforeSend: import("../../../types/chat").Chat | null = null;
  const clearSubmittedEditor = () => {
    if (options.preserveDraft || editor.isDestroyed || editor.state.doc !== submittedEditorDoc) return;
    resetEditorContent(editor, false);
    // The callback also reads attachment/preview state. Publish only after the
    // silent clear so it observes the empty document rather than sent embeds.
    setHasContent(false);
    clearedEditorDoc = editor.state.doc;
  };
  const restoreRejectedDraft = () => {
    if (!contextIsCurrent() || !clearedEditorDoc || editor.isDestroyed || editor.state.doc !== clearedEditorDoc) return;
    editor.commands.setContent(submittedEditorJSON);
    setHasContent(true);
    clearedEditorDoc = null;
  };
  const draftChatIdAtClick = get(draftEditorUIState).currentChatId;
  const sourceDemoIdAtClick = currentChatId && isPublicChat(currentChatId) ? currentChatId : null;
  const chatIdAtClick = sourceDemoIdAtClick
    ? crypto.randomUUID()
    : currentChatId ?? draftChatIdAtClick ?? crypto.randomUUID();
  const embedsReadyAtClick = submittedEmbeds.every((node) =>
    Boolean(node.attrs?.contentRef) &&
    !["uploading", "transcribing", "correcting"].includes(String(node.attrs?.status)));
  const earlyEmptyConnectedAccounts = embedsReadyAtClick
    ? chatSyncService.beginEmptyConnectedAccountLookup() : undefined;
  // A submission with ready embed references can leave the composer before any URL metadata,
  // draft-save, IndexedDB, or transport await. Its raw content stays in local
  // UI memory until the final PII-processed payload replaces the same row.
  if (!options.preserveDraft && embedsReadyAtClick && get(authStore).isAuthenticated
    && !get(forcedLogoutInProgress) && !get(editMessageStore)) {
    try {
      const rawMarkdown = tipTapToCanonicalMarkdown(submittedEditorContent).replace(/^\n+/, "");
      optimisticMessage = createMessagePayload(rawMarkdown, chatIdAtClick, [], teamSenderName);
      const firstTurnAtClick = !currentChatId || (options.firstTurnContextAtClick === true
        && currentChatId === draftChatIdAtClick);
      const provisionalChat = !currentChatId || sourceDemoIdAtClick
        ? ({ chat_id: chatIdAtClick, team_id: sendContext.teamId,
            source_demo_id: sourceDemoIdAtClick, messages_v: 1, title_v: 0, draft_v: 0,
            created_at: optimisticMessage.created_at, updated_at: optimisticMessage.created_at,
            last_edited_overall_timestamp: optimisticMessage.created_at,
          } as import("../../../types/chat").Chat)
        : undefined;
      saveDraftDebounced.cancel();
      noteChatMetadataTurn(chatIdAtClick, "", optimisticMessage.message_id);
      if (firstTurnAtClick && !sendContext.teamId && !sourceDemoIdAtClick && !incognitoMode.get()) {
        initialChatHistoryGate.register(chatIdAtClick, optimisticMessage.message_id);
      }
      dispatch("sendMessage", { message: optimisticMessage, newChat: provisionalChat });
      dispatchedMessage = optimisticMessage;
      optimisticMessageDispatched = true;
      clearSubmittedEditor();
    } catch (error) {
      console.warn("[handleSend] Could not prepare immediate history row:", error);
    }
  }
  // OTel instrumentation: root span covering the entire send pipeline
  const tracer = getTracer();
  const rootSpan = tracer.startSpan('message.send.pipeline', {
    attributes: { 'message.chat_id': currentChatId || 'new' }
  });

  try {

  // The submitted row and editor clear above belong to the click. A saved chat's
  // encrypted model preference may still be restoring; resolve it for that same
  // click before building any durable payload or inference request.
  let selectedChatModel = 'auto';
  if (options.resolveModelSelection) {
    selectedChatModel = await options.resolveModelSelection();
    if (!contextIsCurrent()) return false;
  }

  // This author marker stays in the local Message. The transport builds its own
  // encrypted envelope and the server assigns the authoritative author hash.
  let teamAuthorHash: string | undefined;
  try {
    teamAuthorHash = sendContext.teamId && senderProfile.user_id
      ? await computeSHA256(senderProfile.user_id)
      : undefined;
    await chatDB.ensureReadyForSend();
  } catch (error) {
    console.error("[handleSend] Local send preparation failed:", error);
    return false;
  }
  if (!contextIsCurrent()) return;

  // CRITICAL: Cancel any pending debounced draft save immediately.
  // Without this, fast typing + send within the 1200ms debounce window causes the
  // debounced save to fire AFTER the message is sent, re-saving the already-sent
  // content as a draft. The server also clears drafts on message receipt, but
  // the client's debounced save fires afterwards and re-creates the draft.
  console.debug("[handleSend] Preparing draft/deferred checks", { currentChatId });
  if (!options.preserveDraft && !optimisticMessageDispatched) saveDraftDebounced.cancel();
  const draftStateBeforeSend = get(draftEditorUIState);
  recordSendDebugStep("draft_state_read", {
    currentChatId,
    draftChatId: draftStateBeforeSend.currentChatId,
    isSaveInProgress: draftStateBeforeSend.isSaveInProgress,
  });
  console.debug("[handleSend] Draft state before send", {
    currentChatId,
    draftChatId: draftStateBeforeSend.currentChatId,
    isSaveInProgress: draftStateBeforeSend.isSaveInProgress,
  });
  if (
    draftStateBeforeSend.isSaveInProgress &&
    (!currentChatId ||
      !draftStateBeforeSend.currentChatId ||
      currentChatId === draftStateBeforeSend.currentChatId)
  ) {
    await waitForDraftSaveIdle();
  }

  // OTel: deferred send check span
  console.debug("[handleSend] Starting deferred embed scan", { currentChatId });
  const deferredCheckSpan = tracer.startSpan('message.send.deferred_check');
  recordSendDebugStep("deferred_scan_started", { currentChatId });
  // DEFERRED SEND: Detect embeds that are still in-flight.
  // Instead of blocking with a warning toast, we:
  //  1. Snapshot the editor state into a PendingSendContext (this function).
  //  2. Save the message to IndexedDB with status: "waiting_for_upload".
  //  3. Display it immediately in the chat history for instant visual feedback.
  //  4. When all blocking embeds finish (notified via window 'embedUploadFinished'),
  //     MessageInput.svelte re-runs the actual send path automatically.
  //
  // Blocking statuses:
  //  'uploading'   — file upload to S3 in flight; S3 keys not yet returned.
  //  'transcribing' — audio upload done but transcription pending.
  // NOT blocking:
  //  'processing'  — PDF OCR in flight; we send now and backend fills in OCR later via WebSocket.
  //
  // We collect blocking embed info (id, label) for progress tracking in the UI.
  interface BlockingEmbedInfo {
    id: string;
    label: string;
  }
  const blockingEmbeds: BlockingEmbedInfo[] = [];
  for (const node of submittedEmbeds) {
    if (node.attrs) {
      const st = node.attrs.status as string | undefined;
      if (st === "uploading" || st === "transcribing" || st === "correcting") {
        const label = (node.attrs.filename as string) ||
          (node.attrs.type === "recording" ? "Recording" : "Attachment");
        blockingEmbeds.push({ id: node.attrs.id as string, label });
      }
    }
  }

  deferredCheckSpan.end();
  console.debug("[handleSend] Deferred embed scan complete", {
    currentChatId,
    blockingEmbedCount: blockingEmbeds.length,
  });
  recordSendDebugStep("deferred_scan_complete", {
    currentChatId,
    blockingEmbedCount: blockingEmbeds.length,
  });

  if (blockingEmbeds.length > 0) {
    // -----------------------------------------------------------------------
    // DEFERRED SEND PATH
    // We cannot send right now — one or more embeds are still uploading.
    // Save the message optimistically with status:"waiting_for_upload" and
    // create a PendingSendContext so MessageInput can fire the actual send
    // once all embeds report finished via the embedUploadFinished window event.
    // -----------------------------------------------------------------------

    const deferredTeamId = sendContext.teamId;
    const deferredIncognitoMode = (
      await import("../../../stores/incognitoModeStore")
    ).incognitoMode.get();
    const isOrdinaryDeferredTeamChat =
      Boolean(deferredTeamId) && !isTeamAIInvocation(submittedEditorText);
    if (!contextIsCurrent()) {
      return;
    }
    if (
      isUnsupportedTeamIncognitoContext(
        deferredTeamId,
        deferredIncognitoMode,
      )
    ) {
      console.error(
        "[handleSend] Team chats cannot be queued in incognito mode",
      );
      vibrateMessageField();
      return;
    }

    // Determine / create the chatId exactly as the normal path would.
    // We must replicate just enough of the chat-id resolution logic here so
    // the message lands in the right chat.
    let deferredChatId = currentChatId;
    const draftStateDeferred = get(draftEditorUIState);
    if (!deferredChatId && draftStateDeferred.currentChatId) {
      deferredChatId = draftStateDeferred.currentChatId;
    } else if (!deferredChatId) {
      deferredChatId = crypto.randomUUID();
    }

    // If it's a demo/public chat, allocate a real UUID so the message stores correctly.
    if (deferredChatId && isPublicChat(deferredChatId)) {
      deferredChatId = crypto.randomUUID();
    }

    // Build a stub message payload with status "waiting_for_upload".
    // Content is empty string for now — the real markdown is serialized at dispatch time.
    const deferredMessageId = `${deferredChatId.slice(-10)}-${crypto.randomUUID()}`;
    let deferredNewLocalChat = false;
    const deferredMessage: Message = {
      message_id: deferredMessageId,
      chat_id: deferredChatId,
      role: "user",
      content: "", // Placeholder — overwritten when deferred send fires
      status: "waiting_for_upload",
      created_at: Math.floor(Date.now() / 1000),
      sender_name: teamSenderName,
      hashed_user_id: teamAuthorHash,
      encrypted_content: null,
    };

    // Save stub message to IndexedDB / incognito store so ChatHistory can show it.
    try {
      const { incognitoChatService } =
        await import("../../../services/incognitoChatService");
      const incognitoChat = await legacyEditorProducer.observe(incognitoChatService
        .getChat(deferredChatId)
        .catch(() => null));
      if (!contextIsCurrent()) {
        return;
      }
      if (incognitoChat) {
        await incognitoChatService.addMessage(deferredChatId, deferredMessage);
      } else {
        // Create chat in IndexedDB if it doesn't exist yet
        const existingDeferred = await chatDB.getChat(deferredChatId);
        if (!contextIsCurrent()) {
          return;
        }
        if (existingDeferred && (existingDeferred.team_id ?? null) !== deferredTeamId) {
          console.warn("[handleSend] Deferred chat belongs to a different workspace", { deferredChatId });
          return;
        }
        if (!existingDeferred) {
          const nowDeferred = Math.floor(Date.now() / 1000);
          const newChatForDeferred: import("../../../types/chat").Chat = {
            chat_id: deferredChatId,
            team_id: deferredTeamId,
            encrypted_title: null,
            messages_v: 1,
            title_v: isOrdinaryDeferredTeamChat ? 1 : 0,
            draft_v: 0,
            encrypted_draft_md: null,
            encrypted_draft_preview: null,
            last_edited_overall_timestamp: deferredMessage.created_at,
            unread_count: 0,
            created_at: nowDeferred,
            updated_at: nowDeferred,
            processing_metadata: false,
            waiting_for_metadata:
              !deferredIncognitoMode && !isOrdinaryDeferredTeamChat,
            is_incognito: deferredIncognitoMode,
            source_demo_id: null,
          };
          if (deferredIncognitoMode) {
            await incognitoChatService.storeChat(newChatForDeferred);
            await incognitoChatService.addMessage(
              deferredChatId,
              deferredMessage,
            );
          } else {
            if (newChatForDeferred.team_id) {
              const chatKey = chatKeyManager.createKeyForNewChat(deferredChatId);
              newChatForDeferred.encrypted_chat_key = await wrapTeamChatKey(
                newChatForDeferred.team_id,
                chatKey,
              );
              if (isOrdinaryDeferredTeamChat) {
                newChatForDeferred.encrypted_title = await encryptWithChatKey(
                  teamChatTitleFromMessage(submittedEditorText),
                  chatKey,
                );
              }
            }
            if (!contextIsCurrent()) {
              return;
            }
            await chatDB.addChat(newChatForDeferred);
            await chatDB.saveMessage(deferredMessage);
            deferredNewLocalChat = true;
          }
          window.dispatchEvent(
            new CustomEvent("localChatListChanged", {
              detail: { chat_id: deferredChatId },
            }),
          );
        } else {
          await chatDB.saveMessage(deferredMessage);
          if (draftStateDeferred.currentChatId === deferredChatId && existingDeferred.messages_v === 0) {
            await chatDB.updateChat({ ...existingDeferred, messages_v: 1,
              last_edited_overall_timestamp: deferredMessage.created_at,
              updated_at: Math.floor(Date.now() / 1000) });
            deferredNewLocalChat = true;
          }
        }
      }
    } catch (deferredSaveErr) {
      console.error(
        "[handleSend] Failed to save deferred message to IndexedDB:",
        deferredSaveErr,
      );
      // Fall through — show in UI optimistically even if IDB write failed
    }

    // Snapshot ALL embed nodes in the editor (blocking and non-blocking) so we can
    // reconstruct the final markdown later without needing the live editor.
    // The upload callbacks in embedHandlers.ts will store finished embed data in
    // EmbedStore (with contentRef). The deferred sender reads EmbedStore when it fires.
    const { addPendingSend } =
      await import("../../../stores/pendingUploadStore");
    if (!contextIsCurrent()) {
      return;
    }
    const embedSnapshots = new Map<
      string,
      import("../../../stores/pendingUploadStore").DeferredEmbedSnapshot
    >();
    for (const node of submittedEmbeds) {
      if (node.attrs) {
        const id = node.attrs.id as string;
        embedSnapshots.set(id, {
          embedId: id,
          embedType: (node.attrs.type as string) || "file",
          filename: (node.attrs.filename as string) || "Attachment",
          uploadEmbedId: (node.attrs.uploadEmbedId as string) || null,
          contentRef: (node.attrs.contentRef as string) || null,
          title: (node.attrs.title as string) || null,
          transcript: (node.attrs.transcript as string) || null,
          transcriptOriginal: (node.attrs.transcriptOriginal as string) || null,
          transcriptCorrected: (node.attrs.transcriptCorrected as string) || null,
          useCorrected: (node.attrs.useCorrected as boolean) ?? null,
          correctionModel: (node.attrs.correctionModel as string) || null,
          duration: (node.attrs.duration as string) || null,
          waveform: node.attrs.waveform ?? null,
          model: (node.attrs.model as string) || null,
        });
      }
    }

    // The upload can finish between the initial blocking scan and pending-send
    // registration, which would otherwise miss the only embedUploadFinished event.
    const stillBlockingEmbedIds = new Set(blockingEmbeds.map((e) => e.id));
    for (const { id } of blockingEmbeds) {
      const snapshot = embedSnapshots.get(id);
      if (snapshot?.contentRef) {
        stillBlockingEmbedIds.delete(id);
      }
    }

    // Build per-embed progress map for the store.
    const embedProgressMap = new Map(
      blockingEmbeds.map((e) => {
        const isStillBlocking = stillBlockingEmbedIds.has(e.id);
        return [
          e.id,
          {
            embedId: e.id,
            status: isStillBlocking ? "uploading" : "finished",
            uploadPercent: isStillBlocking ? 0 : 100,
            label: e.label,
          },
        ];
      }),
    );

    const pendingContext = {
      pendingId: `${deferredMessageId}-pending`,
      chatId: deferredChatId,
      messageId: deferredMessageId,
      newLocalChat: deferredNewLocalChat,
      editorSnapshot: submittedEditorContent,
      embedSnapshots,
      blockingEmbedIds: stillBlockingEmbedIds,
      embedProgress: embedProgressMap,
      createdAt: Date.now(),
      piiExclusions: new Set(privacyAtClick.options.excludedIds),
      ignoredEmbedUrls: [...ignoredEmbedUrlsAtClick],
      piiRewriteMappings: structuredClone(privacyAtClick.mappings),
      modelSelection: selectedChatModel,
      partialMarkdown: "",
    };

    // Register in pendingUploadStore.
    // The editor will be CLEARED after this — the user is free to navigate away.
    // When all blocking embeds finish (notified via embedUploadFinished), the
    // deferred sender reconstructs the final markdown from editorSnapshot +
    // EmbedStore data and sends the message without needing the live editor.
    if (!contextIsCurrent()) {
      return;
    }
    if (privacyAtClick.enhanced) deferredSendPrivacy.set(pendingContext, privacyAtClick);
    addPendingSend(pendingContext);

    // Optimistically show the stub message in the chat UI immediately.
    // The message stays at status "waiting_for_upload" until the deferred send fires.
    dispatch("sendMessage", { message: deferredMessage });

    // CLEAR the editor so the user can navigate to other chats, type new messages,
    // and interact freely. Upload callbacks in embedHandlers.ts will try to update
    // TipTap nodes but the nodes won't exist anymore — that's fine, the callbacks
    // already store embed data in EmbedStore independently.
    editor.commands.clearContent(false);
    setHasContent(false);
    if (privacyAtClick.enhanced) {
      deferredSubmittedDrafts.set(pendingContext, { editor, document: editor.state.doc, chatId: deferredChatId });
    }
    editor.commands.blur();

    console.info(
      `[handleSend] Deferred send queued for chat ${deferredChatId.slice(-6)}: blocking on ${stillBlockingEmbedIds.size} embed(s), editor cleared`,
    );
    if (stillBlockingEmbedIds.size === 0) {
      void dispatchPendingSendWithPrivacyRetry(pendingContext);
    }
    rootSpan.setAttribute('message.send.deferred', true);
    queuedDeferredSend = true;
    return true; // Durable deferred queue accepted the message; upload completion sends it.
  }

  const recordingPIIMappings = await redactRecordingFieldsForSend(submittedEditorContent, privacyAtClick);
  privacyAtClick.assertCurrent();

  // OTel: embed registration span (image + audio embeds, includes dynamic imports)
  const embedRegSpan = tracer.startSpan('message.send.embed_registration');
  // =========================================================================
  // UPLOADED IMAGE EMBED REGISTRATION
  // For each 'image' embed that has been successfully uploaded (status: 'finished',
  // uploadEmbedId present), build a TOON content object and store it in EmbedStore.
  // This sets contentRef on the node so serializeEmbedToMarkdown can emit a proper
  // embed reference: ```json\n{"type":"image","embed_id":"..."}\n```
  // =========================================================================
  try {
    // Collect nodes that need contentRef set
    interface UploadedImageNode {
      attrs: Record<string, unknown>;
    }
    const uploadedImageNodes: UploadedImageNode[] = [];
    for (const node of submittedEmbeds) {
      if (node.attrs?.type === "image" && node.attrs.status === "finished" && node.attrs.uploadEmbedId) {
        uploadedImageNodes.push({ attrs: { ...node.attrs } });
      }
    }

    if (uploadedImageNodes.length > 0) {
      const { encode: toonEncode } = await import("@toon-format/toon");
      const { embedStore } = await import("../../../services/embedStore");

      for (const { attrs } of uploadedImageNodes) {
      const uploadEmbedId = attrs.uploadEmbedId as string;

      // Build TOON content mirroring the images/generate embed structure so that
      // existing image crypto utilities (fetchAndDecryptImage) can decrypt and
      // display the image. The images.view skill also expects this shape.
      //
      // embed_ref is set to the filename so that inline embed links like
      // [camera_1772448256162.jpg](embed:camera_1772448256162.jpg) can be
      // resolved via embedStore.resolveByRef() — both in the current session
      // (via the in-memory registerEmbedRef call below) and after reload
      // (via the cold-load path which reads embed_ref from TOON content).
      const embedContent = {
        app_id: "images",
        skill_id: "upload",
        type: "image",
        status: "finished",
        filename: attrs.filename || null,
        embed_ref: attrs.filename || null,
        content_hash: attrs.contentHash || null,
        s3_base_url: attrs.s3BaseUrl || null,
        files: attrs.s3Files || null,
        aes_key: attrs.aesKey || null,
        aes_nonce: attrs.aesNonce || null,
        vault_wrapped_aes_key: attrs.vaultWrappedAesKey || null,
        ai_detection: attrs.aiDetection || null,
      };

      let toonContent: string;
      try {
        toonContent = toonEncode(embedContent);
      } catch {
        toonContent = JSON.stringify(embedContent);
      }

      const now = Date.now();
      const textPreview = (attrs.filename as string) || "Uploaded image";

      // Store in EmbedStore — will be encrypted and sent with the message payload
      await embedStore.put(
        `embed:${uploadEmbedId}`,
        {
          embed_id: uploadEmbedId,
          type: "images-image", // Frontend type for uploaded user images
          status: "finished",
          content: toonContent,
          text_preview: textPreview,
          createdAt: now,
          updatedAt: now,
        },
        "images-image",
      );

      // Register the embed_ref → embed_id mapping in the in-memory index so
      // that inline embed links (e.g. [filename](embed:filename)) resolve
      // immediately in this session without waiting for a cold-load path.
      if (attrs.filename) {
        embedStore.registerEmbedRef(
          attrs.filename as string,
          uploadEmbedId,
          "images",
        );
      }

      console.debug(
        `[handleSend] Registered uploaded image embed ${uploadEmbedId} in EmbedStore`,
      );

      // The click snapshot already contains this canonical reference. The
      // composer may now contain a different draft, so leave its nodes alone.
      setSubmittedEmbedContentRef(submittedEditorContent, uploadEmbedId, attrs.id);
      }
    }
  } catch (embedRegError) {
    console.error(
      "[handleSend] Error registering uploaded image embeds:",
      embedRegError,
    );
    // Non-fatal: message will still send but image embeds may not be stored correctly.
    // Surface the error so it's visible (no silent failures).
    throw embedRegError;
  }

  // =========================================================================
  // AUDIO RECORDING EMBED REGISTRATION
  // For each 'recording' embed that has been successfully uploaded and
  // transcribed (status: 'finished', uploadEmbedId present), build a TOON
  // content object and store it in EmbedStore so the serializer can emit a
  // proper embed reference: ```json\n{"type":"audio-recording","embed_id":"..."}\n```
  // The TOON content stores all S3/AES metadata plus the transcript text so
  // the backend can inject it as context for the LLM.
  // =========================================================================
  try {
    interface UploadedRecordingNode {
      attrs: Record<string, unknown>;
    }
    const uploadedRecordingNodes: UploadedRecordingNode[] = [];
    for (const node of submittedEmbeds) {
      if (node.attrs?.type === "recording" && node.attrs.status === "finished" && node.attrs.uploadEmbedId) {
        uploadedRecordingNodes.push({ attrs: { ...node.attrs } });
      }
    }

    if (uploadedRecordingNodes.length > 0) {
      const { encode: toonEncodeAudio } = await import("@toon-format/toon");
      const { embedStore: audioEmbedStore } =
        await import("../../../services/embedStore");

      for (const { attrs } of uploadedRecordingNodes) {
      const uploadEmbedId = attrs.uploadEmbedId as string;

      // Build TOON content for the audio recording embed.
      // The backend audio skill (transcribe) expects this shape.
      // model is included so RecordingRenderer.ts can display "0:42 · voxtral-mini-2602"
      // in the read-only subtitle when loading from EmbedStore.
      const selectedTranscript = selectAudioTranscriptUseCorrected({
        transcript: attrs.transcript as string | null | undefined,
        transcriptOriginal: attrs.transcriptOriginal as string | null | undefined,
        transcriptCorrected: attrs.transcriptCorrected as string | null | undefined,
        useCorrected: attrs.useCorrected as boolean | null | undefined,
      });
      const embedContent = {
        app_id: "audio",
        skill_id: "transcribe",
        type: "audio-recording",
        status: "finished",
        title: attrs.title || null,
        filename: attrs.filename || null,
        duration: attrs.duration || null,
        waveform: attrs.waveform || null,
        mime_type: attrs.mimeType || null,
        transcript: selectedTranscript.transcript || null,
        transcript_original: attrs.transcriptOriginal || null,
        transcript_corrected: attrs.transcriptCorrected || null,
        use_corrected: typeof attrs.useCorrected === "boolean" ? selectedTranscript.useCorrected : null,
        correction_model: attrs.correctionModel || null,
        model: (attrs.model as string) || null,
        s3_base_url: attrs.s3BaseUrl || null,
        files: attrs.s3Files || null,
        aes_key: attrs.aesKey || null,
        aes_nonce: attrs.aesNonce || null,
        vault_wrapped_aes_key: attrs.vaultWrappedAesKey || null,
      };

      let toonContent: string;
      try {
        toonContent = toonEncodeAudio(embedContent);
      } catch {
        toonContent = JSON.stringify(embedContent);
      }

      const now = Date.now();
      const textPreview =
        (attrs.title as string) ||
        (attrs.transcript as string) ||
        (attrs.filename as string) ||
        "Voice note";

      privacyAtClick.assertCurrent();
      await audioEmbedStore.put(
        `embed:${uploadEmbedId}`,
        {
          embed_id: uploadEmbedId,
          type: "audio-recording",
          status: "finished",
          content: toonContent,
          text_preview: textPreview,
          createdAt: now,
          updatedAt: now,
        },
        "audio-recording",
      );

      console.debug(
        `[handleSend] Registered audio recording embed ${uploadEmbedId} in EmbedStore`,
      );

      setSubmittedEmbedContentRef(submittedEditorContent, uploadEmbedId, attrs.id);
      }
    }
  } catch (recEmbedRegError) {
    console.error(
      "[handleSend] Error registering audio recording embeds:",
      recEmbedRegError,
    );
    throw recEmbedRegError;
  }

  privacyAtClick.assertCurrent();

  // NOTE: PDF embed registration is intentionally NOT done here.
  // PDF dedup is disabled (see internal_api.py). Every PDF upload triggers
  // fresh OCR which delivers the full TOON via send_embed_data. Registering
  // a minimal TOON here would overwrite the full OCR cache on the server.
  embedRegSpan.end();

  // Serialize the submitted click snapshot, including upload references,
  // without incorporating a newer draft typed during registration.
  const editorContent = submittedEditorContent;
  if (
    !editorContent ||
    !editorContent.content ||
    editorContent.content.length === 0
  ) {
    console.warn("[handleSend] No editor content available", {
      currentChatId,
      textLength: editorTextLength,
      editorContent,
    });
    vibrateMessageField();
    return;
  }

  // Convert to markdown
  let markdown = tipTapToCanonicalMarkdown(editorContent);
  recordSendDebugStep("markdown_converted", {
    currentChatId,
    markdownLength: markdown.length,
  });
  console.info("[handleSend] Editor content converted to markdown", {
    currentChatId,
    markdownLength: markdown.length,
  });

  // Strip leading empty lines that were auto-prepended to allow cursor placement
  // before the first embed node (see ensureLeadingParagraph in embedHandlers.ts).
  // Leading newlines are meaningless to the LLM and produce an ugly blank first line.
  markdown = applyChatModelSendRouting(markdown.replace(/^\n+/, ""), selectedChatModel);

  // CRITICAL: Process URLs before sending to convert them to proper embeds
  // This ensures that when user types "summarize https://example.com" and presses Enter,
  // the URL is converted to an embed with metadata fetched from the preview server.
  // The embed will be:
  // 1. Stored in EmbedStore for client-side access
  // 2. Sent with the message to the server
  // 3. Cached server-side for LLM inference (so LLM gets the URL metadata)
  const urlSpan = tracer.startSpan('message.send.url_processing');
  recordSendDebugStep("url_processing_started", { currentChatId });
  try {
    if (get(authStore).isAuthenticated) {
      markdown = await processUrlsBeforeSend(markdown, ignoredEmbedUrlsAtClick);
      recordSendDebugStep("url_processing_complete", {
        currentChatId,
        markdownLength: markdown.length,
      });
    } else {
      // Anonymous free usage is text-only: do not create URL/file embeds or upload metadata.
      recordSendDebugStep("url_processing_skipped_anonymous", { currentChatId });
    }
  } catch (error) {
    console.error("[handleSend] Error processing URLs before send:", error);
    // Continue with original markdown if URL processing fails
    recordSendDebugStep("url_processing_failed", {
      currentChatId,
      error: error instanceof Error ? error.message : String(error),
    });
  } finally {
    urlSpan.end();
  }

  privacyAtClick.assertCurrent();

  // OTel: PII detection span
  const piiSpan = tracer.startSpan('message.send.pii_detection');
  // PII ANONYMIZATION: Detect and replace sensitive data with placeholders
  // This protects user privacy by ensuring emails, API keys, credit cards, etc.
  // are not sent to the server in plain text.
  // Users can click on highlighted PII in the editor to exclude specific matches.
  // The PII mappings are stored encrypted with the message for later restoration.
  //
  // Respects personalDataStore settings:
  // - If masterEnabled is false, skip ALL PII detection
  // - Disabled categories are skipped (user can toggle individual PII types)
  // - User-defined personal data entries (names, addresses, etc.) are also detected
  let piiMappingsForStorage: PIIMapping[] = recordingPIIMappings;
  let privacyExcludedOriginals = new Set<string>();
  recordSendDebugStep("pii_detection_started", { currentChatId });
  try {
    // Outside the dev trial retain the existing final-stage settings read.
    const scanPrivacy = privacyAtClick.enhanced ? privacyAtClick : captureSendPrivacy(privacyAtClick.options.excludedIds ?? new Set());
    const redacted = await redactTextForSend(markdown, scanPrivacy);
    markdown = redacted.markdown;
    piiMappingsForStorage = mergePIIMappingsForStorage(recordingPIIMappings, redacted.mappings);
    privacyExcludedOriginals = redacted.excludedOriginals;
  } catch (error) {
    if (privacyAtClick.enhanced || error instanceof PrivacySendContextChangedError) throw error;
    console.error("[handleSend] Error in PII anonymization:", error);
    recordSendDebugStep("pii_detection_failed", { currentChatId });
  } finally {
    piiSpan.end();
  }
  recordSendDebugStep("pii_detection_complete", {
    currentChatId,
    piiMappingCount: piiMappingsForStorage.length,
  });

  // Check if a new chat suggestion was clicked - if so, track it for deletion
  recordSendDebugStep("suggestion_tracker_import_started", { currentChatId });
  const { consumeClickedSuggestion } =
    await import("../../../stores/suggestionTracker");
  recordSendDebugStep("suggestion_tracker_import_complete", { currentChatId });
  const encryptedSuggestionToDelete = consumeClickedSuggestion();
  recordSendDebugStep("suggestion_consumed", {
    currentChatId,
    hasSuggestionToDelete: !!encryptedSuggestionToDelete,
  });

  if (encryptedSuggestionToDelete) {
    // Delete from local IndexedDB immediately
    try {
      const { chatDB } = await import("../../../services/db");

      const allSuggestions = await chatDB.getAllNewChatSuggestions();

      const suggestionToDelete = allSuggestions.find(
        (s) => s.encrypted_suggestion === encryptedSuggestionToDelete,
      );

      if (suggestionToDelete) {
        // Delete directly by ID instead of re-encrypting text
        // This avoids encryption mismatch issues
        await chatDB.deleteNewChatSuggestionById(suggestionToDelete.id);
      } else {
        console.warn("[handleSend] New chat suggestion not found in DB, skipping deletion");
      }
    } catch (error) {
      console.error("[handleSend] Failed to delete new chat suggestion from local IndexedDB:", error);
      // Continue with message send even if deletion fails
    }
  }

  const isForcedLogoutInProgress = get(forcedLogoutInProgress);
  const isAuthenticatedForSend = get(authStore).isAuthenticated;
  recordSendDebugStep("session_state_checked", {
    currentChatId,
    forcedLogoutInProgress: isForcedLogoutInProgress,
    isAuthenticated: isAuthenticatedForSend,
  });

  if (isForcedLogoutInProgress) {
    console.error(
      "[handleSend] Cannot send message - forced logout in progress",
    );
    notificationStore.error("Session expired. Please log in again.");
    return;
  }

  let chatIdToUse = optimisticMessage ? chatIdAtClick : currentChatId;
  let chatToUpdate: import("../../../types/chat").Chat | null = null;
  let isNewChatCreation = false;
  let didCreateMessagePayload = false;
  let messagePayload: Message; // Defined here to be accessible for sendNewMessage
  let reservedPersonalTurn: PersonalChatTurn | null = null;

  try {
    if (!isAuthenticatedForSend) {
      recordSendDebugStep("anonymous_send_path_started", { currentChatId });
      const anonymousStatus = await refreshAnonymousFreeUsageStatus();
      if (anonymousStatus?.active !== true || anonymousStatus.can_send_text === false) {
        showAnonymousDailyCreditsExhaustedNotification();
        vibrateMessageField();
        return;
      }
      privacyAtClick.assertCurrent();
      const anonymousResult = await anonymousChatStorage.sendTextMessage({
        markdown,
        currentChatId,
        sourceDemoId: currentChatId && isPublicChat(currentChatId) ? currentChatId : null,
        onPending: async (pending) => {
 return legacyEditorProducer.run(async () => {
          dispatch("sendMessage", {
            message: pending.userMessage,
            newChat: pending.isNewChat ? pending.chat : undefined,
          });
          clearSubmittedEditor();

 });
},
      });
      sendAccepted = true;
      if (anonymousResult?.rejectionReason === "anonymous_usage_limit") {
        markAnonymousFreeUsageExhausted();
        showAnonymousDailyCreditsExhaustedNotification();
      }
      if (!options.preserveDraft && clearedEditorDoc && editor.state.doc === clearedEditorDoc) {
        const anonymousDraftChatId = get(draftEditorUIState).currentChatId;
        await clearCurrentDraft(anonymousDraftChatId
          ? { editor, document: clearedEditorDoc, chatId: anonymousDraftChatId }
          : undefined);
      }
      if (anonymousResult?.rejectionReason !== "anonymous_usage_limit") {
        void refreshAnonymousFreeUsageStatus();
      }
      return true;
    }

    recordSendDebugStep("authenticated_send_path_started", { currentChatId });
    if (!contextIsCurrent()) return;

    // Check if there's already a chat with a draft (created during typing)
    const draftState = get(draftEditorUIState);
    if (!chatIdToUse && draftState.currentChatId) {
      // Use the existing chat that was created for the draft
      chatIdToUse = draftState.currentChatId;
      console.info(
        `[handleSend] Using existing draft chat ${chatIdToUse} for message`,
      );
    } else if (!chatIdToUse) {
      // Only create a new chat if there's no current chat and no draft chat
      chatIdToUse = crypto.randomUUID();
      isNewChatCreation = true;
      console.info(`[handleSend] Creating new chat ${chatIdToUse} for message`);
    }

    // CRITICAL: Check if we're sending a message to a demo/legal chat (public chat)
    // If so, we MUST generate a new UUID for the chat so it becomes a regular chat
    // This ensures:
    // 1. The chat can't be identified as demo/legal later
    // 2. Message IDs use proper format {last_10_chars_of_UUID}-{uuid_v4} instead of deriving from a static public-chat ID.
    let sourceDemoId: string | null = sourceDemoIdAtClick;
    if (chatIdToUse && isPublicChat(chatIdToUse)) {
      sourceDemoId = chatIdToUse;
      const oldChatId = chatIdToUse;
      chatIdToUse = crypto.randomUUID();
      isNewChatCreation = true;
      console.info(
        `[handleSend] 🔄 Converting public chat ${oldChatId} to regular chat ${chatIdToUse} - user sent message to demo/legal chat`,
      );
    }

    // Check whether this ID already has a local chat record. ActiveChat stores a
    // temporary new-chat ID in draft state before the chat/key exists; that must
    // not be treated as an existing draft chat.
    recordSendDebugStep("send_chat_classification_started", {
      currentChatId,
      chatIdToUse,
      draftChatId: draftState.currentChatId,
      isNewChatCreation,
    });
    let existingChatCheck: import("../../../types/chat").Chat | null =
      await getRawChatForSendClassification(chatIdToUse);
    if (!existingChatCheck) {
      try {
        const { incognitoChatService } =
          await import("../../../services/incognitoChatService");
        existingChatCheck = await incognitoChatService.getChat(chatIdToUse);
      } catch (incognitoLookupError) {
        console.debug(
          "[handleSend] Incognito chat lookup failed while checking draft chat existence:",
          incognitoLookupError,
        );
      }
    }

    if (!contextIsCurrent()) return;
    if (existingChatCheck && (existingChatCheck.team_id ?? null) !== sendContext.teamId) {
      console.warn("[handleSend] Chat belongs to a different workspace", { chatIdToUse });
      return;
    }

    let existingChatHasUsableKey = false;
    if (existingChatCheck) {
      if (existingChatCheck.is_incognito || isPublicChat(chatIdToUse)) {
        existingChatHasUsableKey = true;
      } else if (chatKeyManager.getKeySync(chatIdToUse)) {
        existingChatHasUsableKey = true;
      }

      const isDraftOnlyChatMissingKey = isDraftOnlyChatMissingDurableKey({
        draftChatId: draftState.currentChatId,
        chatIdToUse,
        existingChat: existingChatCheck,
      });
      if (isDraftOnlyChatMissingKey) {
        console.warn(
          `[handleSend] Draft chat ${chatIdToUse} exists without a usable key; treating it as new chat creation`,
        );
        existingChatCheck = null;
      }
    }

    const isUsingDraftChat = shouldDispatchDraftChatAsNewChat({
      currentChatId,
      draftChatId: draftState.currentChatId,
      chatIdToUse,
      existingChat: existingChatCheck,
      existingChatHasUsableKey,
    });
    chatBeforeSend = existingChatCheck ? { ...existingChatCheck } : null;

    recordSendDebugStep("send_chat_classification_complete", {
      currentChatId,
      chatIdToUse,
      draftChatId: draftState.currentChatId,
      hasExistingChat: !!existingChatCheck,
      existingChatHasUsableKey,
      isUsingDraftChat,
      messagesV: existingChatCheck?.messages_v ?? null,
    });

    // Check if we're dealing with a temporary chat ID (not a real chat in local storage)
    // This happens when ActiveChat pre-allocates a temporaryChatId for the new-chat UI.
    const isTemporaryChat = !existingChatCheck && !isNewChatCreation;
    if (isTemporaryChat) {
      // For temporary chats, we need to create a new chat
      isNewChatCreation = true;
      console.info(
        `[handleSend] Detected temporary chat ID ${chatIdToUse} (not in DB), treating as new chat creation`,
      );
    }

    // No need to fetch current title - server will send metadata after preprocessing

    // =============================================================================
    // AUTO-DISMISS PENDING PERMISSION DIALOG (LOCAL ONLY)
    // =============================================================================
    // If user sends a new message while a permission dialog is visible for this chat,
    // we dismiss it locally WITHOUT sending a WebSocket rejection to the server.
    //
    // WHY LOCAL-ONLY: Sending an explicit rejection via WebSocket triggers the server's
    // _trigger_continuation() which creates a new Celery task for the OLD message.
    // Then the new message ALSO creates a Celery task, resulting in TWO AI responses.
    //
    // Instead, we only create the "rejected" system message locally for UI display.
    // The server's main_processor.py already auto-rejects the pending context when it
    // receives the new message (deletes from Redis + sends dismiss event to other devices).
    const currentPermissionRequestId =
      appSettingsMemoriesPermissionStore.getCurrentRequestId();
    const currentPermissionChatId =
      appSettingsMemoriesPermissionStore.getCurrentChatId();

    if (currentPermissionRequestId && currentPermissionChatId === chatIdToUse) {
      console.info(
        `[handleSend] Auto-dismissing permission dialog locally for request ${currentPermissionRequestId} ` +
          `(user sent new message to chat ${chatIdToUse})`,
      );

      // LOCAL-ONLY dismiss: create "rejected" system message + clear dialog UI
      // Does NOT send WebSocket rejection (avoids duplicate AI response)
      try {
        const { handlePermissionDialogLocalDismiss } =
          await import("../../../services/chatSyncServiceHandlersAppSettings");
        await handlePermissionDialogLocalDismiss(
          chatSyncService,
          currentPermissionRequestId,
        );
        console.info(
          "[handleSend] Permission dialog locally dismissed and rejected response recorded",
        );
      } catch (dismissError) {
        console.error(
          "[handleSend] Error auto-dismissing permission dialog:",
          dismissError,
        );
        // Continue with sending the message even if dismiss fails
        // At minimum, clear the dialog UI
        appSettingsMemoriesPermissionStore.clear();
      }
    }

    // Create new message payload using the processed markdown and determined chatIdToUse
    // The markdown has already been processed to convert URLs to embed references
    // Include PII mappings so they can be encrypted and stored with the message
    const payloadSpan = tracer.startSpan('message.send.payload_creation');
    messagePayload = createMessagePayload(
      markdown,
      chatIdToUse,
      piiMappingsForStorage,
      teamSenderName,
      optimisticMessage?.message_id,
    );
    noteChatMetadataTurn(chatIdToUse, "", messagePayload.message_id);
    registerPersonalPrivacyExclusions(messagePayload, privacyExcludedOriginals);
    messagePayload.hashed_user_id = teamAuthorHash;
    didCreateMessagePayload = true;
    // Reserve before the optimistic IndexedDB write. A second click can start
    // while this one is still doing local work, but may not preflight first.
    if (!existingChatCheck?.team_id && !existingChatCheck?.is_incognito
      && !existingChatCheck?.is_sub_chat && !existingChatCheck?.parent_id) {
      reservedPersonalTurn = reservePersonalChatTurn(chatIdToUse, messagePayload.message_id);
    }
    if (options.preserveDraft) messagePayload.preserve_draft = true;
    ((messagePayload as unknown) as Record<string, unknown>).broadcast = broadcastToSiblings;

    if (!contextIsCurrent()) return;

    // Optimistically cache the last message so the chat list can show "Sending..." immediately
    // (prevents a brief empty chat row while active chat selection/metadata settles)
    chatListCache.setLastMessage(chatIdToUse, messagePayload);
    payloadSpan.end();

    // Show the submitted snapshot as soon as its payload exists. Local chat
    // creation, encryption, and transport can all take time; the composer is
    // available for the next draft while those operations continue.
    const provisionalChat = isNewChatCreation || isUsingDraftChat
      ? (existingChatCheck ?? {
          chat_id: chatIdToUse,
          team_id: sendContext.teamId,
          source_demo_id: sourceDemoId,
          messages_v: 1,
          title_v: 0,
          draft_v: 0,
          created_at: messagePayload.created_at,
          updated_at: messagePayload.created_at,
          last_edited_overall_timestamp: messagePayload.created_at,
        } as import("../../../types/chat").Chat)
      : undefined;
    if (optimisticMessageDispatched) {
      dispatch("sendMessagePrepared", { message: messagePayload });
      dispatchedMessage = messagePayload;
    } else if (!(sendContext.teamId && isNewChatCreation)) {
      if ((isNewChatCreation || isUsingDraftChat) && !sendContext.teamId && !incognitoMode.get()) {
        initialChatHistoryGate.register(chatIdToUse, messagePayload.message_id);
      }
      dispatch("sendMessage", { message: messagePayload, newChat: provisionalChat });
      dispatchedMessage = messagePayload;
      optimisticMessageDispatched = true;
      clearSubmittedEditor();
    }

    // Debug logging to understand the flow
    console.debug(`[handleSend] Chat creation logic:`, {
      currentChatId,
      draftChatId: draftState.currentChatId,
      chatIdToUse,
      isNewChatCreation,
      isUsingDraftChat,
      isTemporaryChat,
    });

    // OTel: IndexedDB write span (chat creation/update + message save)
    const idbSpan = tracer.startSpan('message.send.idb_write');
    // Check if incognito mode is enabled
    const isIncognitoEnabled = incognitoMode.get();

    if (isNewChatCreation) {
      const now = Math.floor(Date.now() / 1000);
      const teamId = sendContext.teamId;
      const isOrdinaryTeamChat = Boolean(teamId) && !isTeamAIInvocation(markdown);
      const newChatData: import("../../../types/chat").Chat = {
        chat_id: chatIdToUse,
        team_id: teamId,
        team_chat_pending_commit: !!teamId,
        encrypted_title: null,
        messages_v: 1, // A new chat with its first message starts at version 1
        title_v: isOrdinaryTeamChat ? 1 : 0,
        draft_v: 0,
        encrypted_draft_md: null,
        encrypted_draft_preview: null,
        last_edited_overall_timestamp: messagePayload.created_at, // Use message timestamp
        unread_count: 0,
        created_at: now,
        updated_at: now,
        processing_metadata: false, // Show chat immediately in sidebar (no longer hidden)
        waiting_for_metadata: !isIncognitoEnabled && !isOrdinaryTeamChat,
        is_incognito: isIncognitoEnabled,
        source_demo_id: sourceDemoId, // Track source for duplication flow
      };

      // Focus/microphone preparation may have generated this key already. Its
      // invisible shell never entered the chat list; the first message remains
      // the sole visible chat creation and does not await preparation.

      if (newChatData.team_id) {
        if (isUnsupportedTeamIncognitoContext(teamId, isIncognitoEnabled)) {
          throw new Error("Team chats cannot be created in incognito mode");
        }
        const chatKey = chatKeyManager.createKeyForNewChat(chatIdToUse);
        newChatData.encrypted_chat_key = await wrapTeamChatKey(
          newChatData.team_id,
          chatKey,
        );
        if (isOrdinaryTeamChat) {
          newChatData.encrypted_title = await encryptWithChatKey(
            teamChatTitleFromMessage(markdown),
            chatKey,
          );
        }
      }

      if (!contextIsCurrent()) return;

      // Duplication Flow: If this chat is from a demo, copy history messages
      if (sourceDemoId) {
        try {
          const { DEMO_CHATS, getDemoMessages } =
            await import("../../../demo_chats");
          const demoMessages = getDemoMessages(
            sourceDemoId,
            DEMO_CHATS,
                    );

          if (demoMessages && demoMessages.length > 0) {
            console.info(
              `[handleSend] Duplicating ${demoMessages.length} demo messages to new chat ${chatIdToUse}`,
            );

            // Ensure we have a chat key for encryption (this device is creating the chat)
            chatKeyManager.createKeyForNewChat(chatIdToUse);

            const { isExampleChat: isExampleChatCheck } =
              await import("../../../demo_chats");
            if (isExampleChatCheck(sourceDemoId)) {
              // Example chat messages contain embed references needed to render
              // embed previews in the cloned chat. Save them to IndexedDB so that
              // the cloned chat displays messages with embeds and the data survives
              // page reloads and cross-device sync.
              for (const demoMsg of demoMessages) {
                await chatDB.saveMessage({
                  ...demoMsg,
                  chat_id: chatIdToUse,
                  message_id: `${chatIdToUse}-${demoMsg.message_id}`,
                });
              }
              console.info(
                `[handleSend] Saved ${demoMessages.length} example messages to IndexedDB for cloned chat ${chatIdToUse}`,
              );
              newChatData.messages_v = demoMessages.length + 1;
            } else {
              // NOTE: Demo messages are NOT saved to IndexedDB. They were previously
              // copied as AI "context", but the backend receives full conversation context
              // via the API call — storing them in IDB caused demo messages to bleed into
              // the real chat view when IDB was reloaded after streaming completed.
              // The demo greeting ("Digital team mates for everyone...") is not meaningful
              // context for the AI response to the user's actual question.

              // Update messages_v count (only the new user message being sent)
              newChatData.messages_v = 1;
            }
          }

          // Clone example chat embeds into the embedStore (IndexedDB)
          // Without this, embeds only render from the in-memory exampleChatStore
          // fallback — they won't survive cross-device sync or backend AI context.
          const { isExampleChat: isExampleChatCheck, getExampleChatEmbeds } =
            await import("../../../demo_chats");
          if (isExampleChatCheck(sourceDemoId)) {
            const exampleEmbeds = getExampleChatEmbeds(sourceDemoId);
            if (exampleEmbeds.length > 0) {
              const { embedStore: embedStoreForClone } =
                await import("../../../services/embedStore");
              console.info(
                `[handleSend] Cloning ${exampleEmbeds.length} embeds from example chat ${sourceDemoId} to new chat ${chatIdToUse}`,
              );
              for (const embed of exampleEmbeds) {
                const contentRef = `embed:${embed.embed_id}`;
                try {
                  await embedStoreForClone.put(
                    contentRef,
                    {
                      content: embed.content,
                      type: embed.type,
                      status: "finished",
                      embed_id: embed.embed_id,
                      parent_embed_id: embed.parent_embed_id,
                      embed_ids: embed.embed_ids,
                    },
                    embed.type as import("../../../message_parsing/types").EmbedType,
                  );
                } catch (embedError) {
                  console.warn(
                    `[handleSend] Failed to clone embed ${embed.embed_id}:`,
                    embedError,
                  );
                }
              }
            }
          }
        } catch (dupError) {
          console.error(
            "[handleSend] Error duplicating demo history:",
            dupError,
          );
        }
      }

      console.debug(
        `[handleSend] Creating new ${isIncognitoEnabled ? "incognito" : "regular"} chat with waiting_for_metadata=${newChatData.waiting_for_metadata}:`,
        {
          chatId: chatIdToUse,
          waiting_for_metadata: newChatData.waiting_for_metadata,
        },
      );

      if (isIncognitoEnabled) {
        // Create incognito chat in sessionStorage
        const { incognitoChatService } =
          await import("../../../services/incognitoChatService");
        await incognitoChatService.storeChat(newChatData);
        createdLocalChatId = chatIdToUse;
        await incognitoChatService.addMessage(chatIdToUse, messagePayload);
        persistedMessageId = messagePayload.message_id;
        messageStoredIncognito = true;
        chatToUpdate = newChatData;
        console.info(
          `[handleSend] Created new incognito chat ${chatIdToUse} and saved its first message.`,
        );
      } else {
        // Create regular chat in IndexedDB
        if (!contextIsCurrent()) return;
        await chatDB.addChat(newChatData); // Save new chat metadata
        forgetPreparedChatForSend(chatIdToUse);
        createdLocalChatId = chatIdToUse;
        await chatDB.saveMessage(messagePayload); // Save the first message separately
        persistedMessageId = messagePayload.message_id;

        // Fetch the chat again to ensure we have the consistent DB version for chatToUpdate
        // This also ensures chatToUpdate has the correct messages_v (which is 1)
        chatToUpdate = await chatDB.getChat(chatIdToUse);
        if (!chatToUpdate) {
          recordSendDebugStep("send_aborted_created_chat_missing", {
            currentChatId,
            chatIdToUse,
          });
          console.error(
            `[handleSend] CRITICAL: Newly created chat ${chatIdToUse} not found in DB immediately after addChat and saveMessage.`,
          );
          vibrateMessageField();
          return;
        }
        console.info(
          `[handleSend] Created new local chat ${chatIdToUse} and saved its first message (messages_v should be 1).`,
        );
      }

      // Dispatch event to update chat list immediately
      window.dispatchEvent(
        new CustomEvent("localChatListChanged", {
          detail: { chat_id: chatIdToUse },
        }),
      );
    } else {
      // Existing chat: Save the new message and update chat metadata
      if (!contextIsCurrent()) return;
      // Check if it's an incognito chat
      const { incognitoChatService } =
        await import("../../../services/incognitoChatService");
      let isIncognitoChat = false;
      let existingChat: import("../../../types/chat").Chat | null = null;

      try {
        existingChat = await incognitoChatService.getChat(chatIdToUse);
        if (existingChat) {
          isIncognitoChat = true;
        }
      } catch {
        // Not an incognito chat, continue to check IndexedDB
      }

      if (isIncognitoChat && existingChat) {
        // Update incognito chat
        await incognitoChatService.addMessage(chatIdToUse, messagePayload);
        persistedMessageId = messagePayload.message_id;
        messageStoredIncognito = true;
        existingChat.messages_v = (existingChat.messages_v || 0) + 1;
        existingChat.last_edited_overall_timestamp = messagePayload.created_at;
        existingChat.updated_at = Math.floor(Date.now() / 1000);
        await incognitoChatService.updateChat(chatIdToUse, {
          messages_v: existingChat.messages_v,
          last_edited_overall_timestamp:
            existingChat.last_edited_overall_timestamp,
          updated_at: existingChat.updated_at,
        });
        chatToUpdate = existingChat;
        console.info(
          `[handleSend] Updated incognito chat ${chatIdToUse} with new message.`,
        );
      } else {
        // Update regular chat in IndexedDB
        if (!contextIsCurrent()) return;
        await chatDB.saveMessage(messagePayload);
        persistedMessageId = messagePayload.message_id;

        // Sub-chat sibling broadcast logic
        if (broadcastToSiblings) {
          try {
            const { getAllChats } = await import("../../../services/db/chatCrudOperations");
            const allChats = await getAllChats(chatDB);
            const currentChatRecord = await chatDB.getChat(chatIdToUse);
            if (currentChatRecord && currentChatRecord.parent_id) {
              const siblings = allChats.filter(c => c.parent_id === currentChatRecord.parent_id && c.chat_id !== chatIdToUse);
              const { generateUUID } = await import("../../../message_parsing/utils");
              for (const sib of siblings) {
                const sibMsgId = `${sib.chat_id.slice(-10)}-${generateUUID()}`;
                const sibMsgPayload = {
                  ...messagePayload,
                  message_id: sibMsgId,
                  chat_id: sib.chat_id,
                };
                await chatDB.saveMessage(sibMsgPayload);
                console.debug(`[handleSend:Broadcast] Saved message copy to sibling sub-chat: ${sib.chat_id}`);
                privacyAtClick.assertCurrent();
                await chatSyncService.sendNewMessage(sibMsgPayload);
              }
            }
          } catch (err) {
            console.error('[handleSend:Broadcast] Error broadcasting to siblings:', err);
          }
        }
        existingChat = await chatDB.getChat(chatIdToUse);
        if (existingChat) {
          existingChat.messages_v = (existingChat.messages_v || 0) + 1;
          existingChat.last_edited_overall_timestamp =
            messagePayload.created_at;
          existingChat.updated_at = Math.floor(Date.now() / 1000);

          // A wiki question is a separate submission, so the composer's draft stays intact.
          if (!options.preserveDraft) {
            existingChat.cleared_draft_v = Math.max(existingChat.cleared_draft_v ?? 0, existingChat.draft_v ?? 0);
            existingChat.encrypted_draft_md = null;
            existingChat.encrypted_draft_preview = null;
            existingChat.draft_v = 0;
          }

          await chatDB.updateChat(existingChat);
          chatToUpdate = existingChat;

          if (isUsingDraftChat) {
            console.info(
              `[handleSend] Updated existing draft chat ${chatIdToUse} with first message and cleared draft fields`,
            );
          } else {
            console.info(
              `[handleSend] Updated existing chat ${chatIdToUse} with new message and cleared draft fields`,
            );
          }
        } else {
          recordSendDebugStep("send_aborted_existing_chat_missing", {
            currentChatId,
            chatIdToUse,
            isUsingDraftChat,
          });
          console.error(
            `[handleSend] Existing chat ${chatIdToUse} not found when trying to add a message.`,
          );
          vibrateMessageField();
          return; // Early exit if chat doesn't exist
        }
      }
    }

    idbSpan.end();

    // A context switch during IndexedDB work must not select the old chat in
    // the new workspace or send an active-chat update for it.
    if (!contextIsCurrent()) return;

    // If chatToUpdate is null at this point, the local DB operation failed.
    if (!chatToUpdate) {
      recordSendDebugStep("send_aborted_chat_update_missing", {
        currentChatId,
        chatIdToUse,
      });
      console.error(
        `[handleSend] Failed to update local chat ${chatIdToUse} with new message. Aborting send.`,
      );
      vibrateMessageField();
      return;
    }

    // Check if there's an active AI task for this chat
    // If so, the new message will be queued on the server
    // We don't cancel the existing task - it will complete and then process the queued message
    if (chatIdToUse && chatSyncService) {
      const existingTaskId =
        chatSyncService.getActiveAITaskIdForChat(chatIdToUse);
      if (existingTaskId) {
        console.info(
          `[handleSend] Active AI task ${existingTaskId} exists for chat ${chatIdToUse}. New message will be queued.`,
        );
        // TODO: Show UI message "Press enter again to stop previous response" or similar
        // This will be handled by the frontend when it receives a queue notification
      }
    }


    // ─── Edit mode: delete messages from edit point before re-sending ───
    // When the user edits a previous message, we need to delete all messages
    // from that point onward (inclusive) so the backend sees a clean history.
    const editState = get(editMessageStore);
    const isEditSend = !options.preserveDraft && !!(editState && editState.chatId === chatIdToUse);
    let editCreatedAt: number | undefined;
    if (isEditSend && editState) {
      editCreatedAt = editState.createdAt;
      try {
        const allMessages = await chatDB.getMessagesForChat(chatIdToUse);
        allMessages.sort((a, b) => (a.created_at ?? 0) - (b.created_at ?? 0));
        // Find the index of the edited message by ID for precision
        const editIdx = allMessages.findIndex(m => m.message_id === editState.messageId);
        const startIdx = editIdx >= 0 ? editIdx : allMessages.findIndex(m => (m.created_at ?? 0) >= editState.createdAt);
        if (startIdx >= 0) {
          const messagesToDelete = allMessages.slice(startIdx);
          console.debug(`[handleSend] Edit mode: deleting ${messagesToDelete.length} messages from index ${startIdx}`);
          for (const msg of messagesToDelete) {
            await chatDB.deleteMessage(msg.message_id);
            legacyEditorProducer.observe(chatSyncService.sendDeleteMessage(chatIdToUse, msg.message_id).catch(err => {
              console.warn('[handleSend] Edit mode: failed to delete message from server:', msg.message_id, err);
            }));
          }
        }
      } catch (err) {
        console.error('[handleSend] Edit mode: failed to delete messages:', err);
      }
      cancelEdit();
    }

    if (isSendCancelled(chatIdToUse)) {
      await chatDB.deleteMessage(messagePayload.message_id);
      recordSendDebugStep("send_cancelled_before_dispatch", {
        chatIdToUse,
        messageId: messagePayload.message_id,
      });
      return;
    }

    // OTel: UI dispatch span — the moment message becomes visible
    if (!contextIsCurrent()) return;
    const uiSpan = tracer.startSpan('message.send.ui_dispatch');
    // Dispatch for UI update (ActiveChat will pick this up)
    // The messagePayload is already defined and includes the correct chat_id
    // If it's a new chat (isNewChatCreation is true) OR we're using an existing draft chat,
    // chatToUpdate will hold the Chat object.
    recordSendDebugStep("local_message_dispatch_started", {
      currentChatId,
      chatIdToUse,
      messageId: messagePayload.message_id,
      isNewChatCreation,
      isUsingDraftChat,
    });
    // The same message_id was inserted before the IndexedDB write. Avoid a
    // second history event, which can reinitialize a newly created chat.
    if (!optimisticMessageDispatched) {
      dispatch("sendMessage", {
        message: messagePayload,
        newChat: isNewChatCreation || isUsingDraftChat ? chatToUpdate : undefined,
        isEditSend,
        editCreatedAt,
      });
      dispatchedMessage = messagePayload;
      optimisticMessageDispatched = true;
      clearSubmittedEditor();
    }
    console.info("[handleSend] Dispatched local user message", {
      chatId: messagePayload.chat_id,
      messageId: messagePayload.message_id,
      isNewChatCreation,
      isUsingDraftChat,
      contentLength: messagePayload.content.length,
    });
    recordSendDebugStep("local_message_dispatched", {
      currentChatId,
      chatIdToUse,
      messageId: messagePayload.message_id,
      isNewChatCreation,
      isUsingDraftChat,
    });

    // chatToUpdate should be the definitive version of the chat from the DB
    // The 'chatUpdated' event is still useful for other components like the chat list.
    if (chatToUpdate) {
      // Dispatch chatUpdated so other parts of the UI (like chat list) can update if needed
      // This local dispatch is for MessageInput's parent (ActiveChat)
      dispatch("chatUpdated", { chat: chatToUpdate });

      // If a new chat was created, signal it through draftEditorUIState
      // This is what Chats.svelte listens to for selecting new chats.
      if (isNewChatCreation && !options.preserveDraft) {
        draftEditorUIState.update((state) => ({
          ...state,
          newlyCreatedChatIdToSelect: chatIdToUse,
        }));
        console.info(
          `[handleSend] Signaled new chat ${chatIdToUse} for selection via draftEditorUIState.`,
        );
      } else {
        // For existing chats, ensure chatSyncService knows about the local update
        // so it can propagate to Chats.svelte if necessary, or handle consistency.
        // A more direct way for Chats.svelte to react to local DB changes might be needed
        // if chatSyncService events are strictly for server-originated changes.
        // For now, we rely on draftEditorUIState for new chats, and existing chat updates
        // should be picked up by Chats.svelte if it re-queries DB on 'chatUpdated' from ActiveChat.
        window.dispatchEvent(
          new CustomEvent("chatUpdated", {
            // This helps Chats.svelte if it listens globally or via ActiveChat relay
            detail: { chat_id: chatToUpdate.chat_id, chat: chatToUpdate }, // Ensure chat_id is at top level for some handlers
            bubbles: true,
            composed: true,
          }),
        );
      }
    }

    uiSpan.end();

    if (isSendCancelled(chatIdToUse)) {
      await chatDB.deleteMessage(messagePayload.message_id);
      recordSendDebugStep("send_cancelled_after_dispatch", {
        chatIdToUse,
        messageId: messagePayload.message_id,
      });
      return;
    }

    recordSendPreparationPhase('local_message_ready');
    // OTel: WebSocket send span (encryption + WS dispatch happens inside sendNewMessage)
    const wsSpan = tracer.startSpan('message.send.ws_send');
    // CRITICAL: Notify backend about the active chat BEFORE sending the message
    // This prevents race conditions where the backend starts processing the message
    // and tries to stream chunks before knowing which chat is active, causing chunks to be dropped
    // This is especially important for new chats where the active_chat might be null or the old chat ID
		recordSendDebugStep("send_set_active_chat_started", {
			chatIdToUse,
			messageId: messagePayload.message_id,
		});
		if (!contextIsCurrent()) return;
		recordSendPreparationPhase('set_active_chat_begin');
		void legacyEditorProducer.observe(legacyEditorProducer.observe(chatSyncService.sendSetActiveChat(chatIdToUse).then(() => {
			recordSendPreparationPhase('set_active_chat_ready');
			recordSendDebugStep("send_set_active_chat_complete", {
				chatIdToUse, messageId: messagePayload.message_id,
			});
		})).catch((error) => {
			console.warn("[handleSend] Active chat notification failed", error);
		}));
    console.debug(
      "[handleSend] Notified backend about active chat before sending message:",
      chatIdToUse,
    );

    if (isSendCancelled(chatIdToUse)) {
      await chatDB.deleteMessage(messagePayload.message_id);
      recordSendDebugStep("send_cancelled_before_websocket", {
        chatIdToUse,
        messageId: messagePayload.message_id,
      });
      wsSpan.end();
      return;
    }

    if (!contextIsCurrent()) return;

    // Send message to backend via chatSyncService
    // Include encrypted suggestion for deletion if one was clicked
    const serverMessagePayload = e2eServerContentOverride
      ? ({ ...messagePayload, testMockMarker: e2eServerContentOverride.testMockMarker } as Message & { testMockMarker: string })
      : messagePayload;
		recordSendDebugStep("send_new_message_started", {
			chatIdToUse,
			messageId: messagePayload.message_id,
		});
		recordSendPreparationPhase('send_new_message_begin');
		privacyAtClick.assertCurrent();
		await chatSyncService.sendNewMessage(
			serverMessagePayload,
			encryptedSuggestionToDelete,
			undefined,
			projectFocusIntent ?? undefined,
			isNewChatCreation || isUsingDraftChat,
			earlyEmptyConnectedAccounts,
		);
    recordSendDebugStep("send_transport_resolved");
    // A local admission guard can resolve after marking the message failed.
    // Every composer must retain its draft on rejection; cleanup requires acceptance.
    recordSendDebugStep("send_admission_read_started");
    const submittedMessage = await chatDB.getMessage(messagePayload.message_id);
    recordSendDebugStep("send_admission_read_complete");
    if (submittedMessage?.status === 'failed') {
      wsSpan.end();
      return false;
    }
    sendAccepted = true;
		recordSendDebugStep("send_new_message_complete", {
			chatIdToUse,
			messageId: messagePayload.message_id,
		});
    console.debug(
      "[handleSend] Message sent to chatSyncService:",
      {
        chatId: messagePayload.chat_id,
        messageId: messagePayload.message_id,
        contentLength: messagePayload.content?.length ?? 0,
        hasSuggestionToDelete: !!encryptedSuggestionToDelete,
      },
    );

    const wasCancelledAfterSend = isSendCancelled(chatIdToUse);
    if (wasCancelledAfterSend) {
      recordSendDebugStep("send_cancelled_message_delete_started");
      await chatDB.deleteMessage(messagePayload.message_id);
      recordSendDebugStep("send_cancelled_message_delete_complete");
      recordSendDebugStep("send_cancelled_remote_delete_started");
      await chatSyncService.sendDeleteMessage(chatIdToUse, messagePayload.message_id);
      recordSendDebugStep("sent_message_deleted_after_cancellation", {
        chatIdToUse,
        messageId: messagePayload.message_id,
      });
    }

    wsSpan.end();

    if (!contextIsCurrent()) return true;

    const composerStillContainsSentDocument = editor.state.doc === submittedEditorDoc;
    const composerStillContainsClearedDocument = !!clearedEditorDoc && editor.state.doc === clearedEditorDoc;
    if (!options.preserveDraft && !wasCancelledAfterSend && composerStillContainsSentDocument) {
      resetEditorContent(editor, false);
      setHasContent(false);
    }

    // OTel: cleanup span (draft clearing)
    const cleanupSpan = tracer.startSpan('message.send.cleanup');
    // After successfully sending the message, clear the draft for this chat
    // Ensure we only clear if the message was for the chat currently in the draft editor's context
    const currentDraftState = get(draftEditorUIState);
    if (!options.preserveDraft && !isSendCancelled(chatIdToUse) && (composerStillContainsSentDocument || composerStillContainsClearedDocument) && chatIdToUse && currentDraftState.currentChatId === chatIdToUse) {
      console.info(
        `[handleSend] Message sent for chat ${chatIdToUse}, clearing its draft.`,
      );
      recordSendDebugStep("send_draft_cleanup_started");
      await clearCurrentDraft({ editor, document: composerStillContainsClearedDocument ? clearedEditorDoc! : submittedEditorDoc, chatId: chatIdToUse });
      recordSendDebugStep("send_draft_cleanup_complete");
    } else {
      // This case might happen if a message is sent for a chat that isn't the one
      // currently active in the MessageInput's draft context (e.g., programmatic send).
      // Or if a new chat was just created, the draft context might not be set yet,
      // but clearCurrentDraft relies on draftEditorUIState.currentChatId.
      // If it's a new chat, there shouldn't be a draft to clear anyway.
      // If it's an existing chat but not the one in draft context, we might not want to clear its draft.
      // The current logic of clearCurrentDraft uses draftEditorUIState.currentChatId,
      // so if chatIdToUse is different, it won't clear the draft of chatIdToUse unless
      // draftEditorUIState.currentChatId happens to be chatIdToUse.
      // This seems fine for now, as sending a message typically implies the chat is active.
      console.debug(
        `[handleSend] Message sent for chat ${chatIdToUse}, but draft context is ${currentDraftState.currentChatId}. Draft clear skipped or handled by clearCurrentDraft's internal logic.`,
      );
    }
    cleanupSpan.end();
    return !wasCancelledAfterSend;
  } catch (error) {
    if ((isPreflightAcknowledgementTimeout(error) || error instanceof PendingAdmissionCompatibilityError) && persistedMessageId) {
      // The sender retained this exact ID for reconnect as waiting_for_internet.
      sendAccepted = true;
      return true;
    }
    if (sendAccepted) {
      console.error('[handleSend] Message accepted but draft cleanup failed:', error);
      return true;
    }
    const failedAfterStep = (window as Window & {
      __openmatesLastSendDebug?: { step?: unknown };
    }).__openmatesLastSendDebug?.step;
    recordSendDebugStep("send_failed", {
      currentChatId,
      chatIdToUse,
      hasMessagePayload: didCreateMessagePayload,
      failedAfterStep,
      error: serializeSendDebugError(error),
    });
    if (error instanceof AnonymousFreeUsageExhaustedError) {
      markAnonymousFreeUsageExhausted(error.reason);
      restoreRejectedDraft();
      showAnonymousDailyCreditsExhaustedNotification();
      if (editor && !editor.isDestroyed) setHasContent(true);
      vibrateMessageField();
      return;
    }
    if (isPreflightAcknowledgementTimeout(error)) {
      console.warn("Failed to handle message send; retrying after reconnect:", error);
    } else {
      console.error("Failed to handle message send:", error);
    }
    vibrateMessageField();
  } finally {
    if (!sendAccepted && reservedPersonalTurn) {
      failPersonalChatTurn(reservedPersonalTurn, new Error('Local chat send did not dispatch.'));
    }
    // CRITICAL: Always release the send guard, even on error,
    // so the user can retry sending after a failure.
  }
  } catch (error) {
    if (error instanceof PrivacyScanFailedError || error instanceof PrivacySendContextChangedError) {
      return false;
    }
    throw error;
  } finally {
    if (!sendAccepted && !queuedDeferredSend) {
      if (createdLocalChatId || persistedMessageId) {
        recordSendDebugStep("send_rollback_started");
        try {
          if (messageStoredIncognito) {
            const { incognitoChatService } = await import("../../../services/incognitoChatService");
            if (createdLocalChatId) {
              await incognitoChatService.deleteChat(createdLocalChatId);
            } else if (persistedMessageId && dispatchedMessage) {
              const keptMessages = (await incognitoChatService.getMessagesForChat(dispatchedMessage.chat_id))
                .filter(message => message.message_id !== persistedMessageId);
              await incognitoChatService.storeMessages(dispatchedMessage.chat_id, keptMessages);
              if (chatBeforeSend) await incognitoChatService.updateChat(dispatchedMessage.chat_id, chatBeforeSend);
            }
          } else if (createdLocalChatId) {
            await chatDB.deleteChat(createdLocalChatId);
            chatListCache.removeChat(createdLocalChatId);
            window.dispatchEvent(new CustomEvent("localChatListChanged", {
              detail: { chat_id: createdLocalChatId },
            }));
          } else if (persistedMessageId && dispatchedMessage) {
            await chatDB.deleteMessage(persistedMessageId);
            const currentChat = await chatDB.getChat(dispatchedMessage.chat_id);
            if (chatBeforeSend && currentChat?.messages_v === (chatBeforeSend.messages_v ?? 0) + 1) {
              await chatDB.updateChat({ ...currentChat,
                messages_v: chatBeforeSend.messages_v,
                last_edited_overall_timestamp: chatBeforeSend.last_edited_overall_timestamp,
                encrypted_draft_md: chatBeforeSend.encrypted_draft_md,
                encrypted_draft_preview: chatBeforeSend.encrypted_draft_preview,
                draft_v: chatBeforeSend.draft_v,
                cleared_draft_v: chatBeforeSend.cleared_draft_v,
              });
            }
          }
        } catch (rollbackError) {
          console.error("[handleSend] Failed to roll back rejected local message:", rollbackError);
        }
        recordSendDebugStep("send_rollback_complete");
      }
      restoreRejectedDraft();
      if (optimisticMessageDispatched && dispatchedMessage) {
        dispatch("sendMessageRejected", {
          chatId: dispatchedMessage.chat_id,
          messageId: dispatchedMessage.message_id,
        });
      }
    }
    rootSpan.end();
  }
  } finally {
    // Synchronous snapshot/tracing preparation above can throw before the
    // pipeline's rollback block exists. Every acquired guard must be released.
    sendInProgress = false;
    activeSendDebugPhase = null;
    recordSendDebugStep("send_guard_released");
  }

 });
}

